(window.GIM_TS=window.GIM_TS||{})["Bava Batra.7"]={"from":168,"a":[["ואולם אם \u0003פירקן\u0004 את המשאות מעל החמורים והפועלים \u0003והכניסן לתוך ביתו,\u0004 במקרה זה, אם \u0003פסק\u0004 דמים \u0003עד שלא מדד\u0004 — \u0003אין שניהן יכולין\u0004 עוד \u0003לחזור בהן,\u0004 אבל אם \u0003מדד עד שלא פסק\u0004 — \u0003שניהן יכולין לחזור בהן. ו\u0004נלמד מכאן שכשם ש\u0003כליו\u0004 של \u0003מוכר ברשות לוקח לא קנה\u0004 המוכר, שהרי משעה שפירקם והכניסם לביתו זכה הלוקח בפירות, אפילו בכליו של המוכר, ומכאן שהרשות היא הקובעת ולא הכלי, לכן גם \u0003כליו\u0004 של \u0003לוקח נמי\u0004 \u0005[גם כן]\u0006 \u0003ברשות מוכר לא קנה!\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לומר כאן שאין מדובר שהניח את הפירות ברשות הלוקח כשהם עדיין בכלי המוכר, אלא \u0003בששפכן\u0004 על הקרקע, אבל בכלים — לא היה הלוקח קונה. \u0003איקפד\u0004 \u0005[הקפיד]\u0006 \u0003רבא\u0004 על דחיה זו של רב נחמן בר יצחק: \u0003מידי\u0004 \u0005[כלום]\u0006 \u0003\"שפכן\" קתני\u0004 \u0005[שנינו]?\u0006 הלא \u0003\"פירקן\" קתני\u0004 \u0005[שנינו]!\u0006 משמע שפירק את הדברים שהיו על החמרים, והם השקים של המוכר, בתוך רשותו של הלוקח! \u0003אלא אמר מר בר רב אשי:\u0004 אפשר לדחות באופן אחר, שכאן מדובר לא בדברים שהיו נתונים בשקים, אלא \u0003במתאכלי דתומי\u0004 \u0005[בצרורות של שום]\u0006 שהיו קשורים זה בזה ולא בשק.","לגופו של דבר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003מר זוטרא לרבינא: מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003\"פירקן\" קתני\u0004 \u0005[שנינו],\u0006 שהקנין נעשה על ידי פריקת החפצים, ואם כן הוא \u0003מה לי\u0004 אם \u0003פסק\u0004 וקבע מחיר \u0003ומה לי לא פסק? אמר ליה\u0004 \u0005[לו]:\u0006 ההבדל הוא כך, אם \u0003פסק\u0004 וקבע מחיר — \u0003סמכא דעתיה\u0004 \u0005[סומכת דעתו]\u0006 והסכמת הלב היא שעושה את הקנין, \u0003לא פסק\u0004 — \u0003לא סמכא דעתיה\u0004 \u0005[סומכת דעתו]\u0006 ועדיין לא נגמר הקנין. ומכל מקום שוב לא מצאנו ראיה גמורה לבעיית כלי לוקח ברשות מוכר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 פסק הלכה: \u0003כליו של אדם קונה לו בכל מקום.\u0004 ונברר: הלשון \"בכל מקום\" \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 \u0003לאו לאתויי\u0004 \u0005[האם לא להביא]\u0006 \u0003רשות מוכר?\u0004 ענה לו רב אשי: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במקרה מיוחד, \u0003דאמר ליה\u0004 \u0005[שאמור לו\u0006 המוכר\u0005]:\u0006 \u0003זיל קני\u0004 \u0005[לך\u0006 ו\u0005קנה],\u0006 ובמקרה כזה בוודאי יש קנין. אבל אנו מדברים בסתם, ולא נפתרה איפוא הראיה.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת קידושין\u0005]:\u0006 \u0003נכסים שיש להן אחריות\u0004 (מקרקעין) — \u0003נקנין בכסף ובשטר ובחזקה. ושאין להן אחריות\u0004 — \u0003אין נקנין אלא במשיכה.\u0004 ועל כך הוסיפו הלכה, ש\u0003בסורא מתנו לה להא שמעתא משמיה\u0004 \u0005[היו שונים אותה ההלכה משמו]\u0006 של \u0003רב חסדא, בפומבדיתא מתנו לה משמיה\u0004 \u0005[היו שונים אותה משמו]\u0006 של \u0003רב כהנא, ואמרי לה משמיה\u0004 \u0005[ויש אומרים אותה משמו]\u0006 של \u0003רבא\u0004 וכך לשונה: \u0003לא שנו\u0004 שמיטלטלין נקנים במשיכה, \u0003אלא\u0004 ב\u0003דברים שאין דרכן להגביה,\u0004 כלומר, שאין דרך להגביה אותם, מחמת כובדם וכדומה, \u0003אבל דברים שדרכן להגביה\u0004 — \u0003בהגבהה אין\u0004 \u0005[כן]\u0006 קונה אותם, \u0003במשיכה לא.\u0004","\u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003אביי וקאמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו],\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אדא בר מתנה לאביי\u0004 ממה ששנינו: \u0003הגונב כיס\u0004 (שק קטן) \u0003בשבת\u0004 — \u0003חייב\u0004 בתשלום עבור הכיס, למרות שהיה חילול שבת בדבר והגנב חייב מיתה על עבירה זו, ואף שכרגיל במקום מיתה פטור מן התשלומים. ומדוע? — \u0003שכבר נתחייב בגניבה קודם שיבא לידי איסור שבת,\u0004 שהרי קודם הגביה את החפץ לגונבו ורק אחר כך הוציאו לרשות הרבים, אבל אם","\u0003היה מגרר\u0004 (גורר, מושך) \u0003ויוצא, מגרר ויוצא\u0004 — \u0003פטור, שהרי איסור שבת\u0004 של הוצאה לרשות הרבים, \u0003ו\u0004איסור \u0003גניבה\u0004 שקנה את החפץ כשהוציאו מרשות בעליו \u0003באין כאחד,\u0004 ובמקרה זה חל עליו רק החיוב החמור יותר, שהוא חיוב המיתה על חילול השבת.","ויש להקשות: \u0003והרי כיס דבר\u0004 \u0005[שבן]\u0006 \u0003הגבהה הוא, ואפילו הכי\u0004 \u0005[כך]\u0006 רואים ש\u0003קני\u0004 \u0005[קונה]\u0006 אותו \u0003במשיכה\u0004 (\"מגרר ויוצא\")! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: כאן מדובר \u0003במיתנא\u0004 \u0005[בחבל],\u0006 שמשכו בחבל. אמר לו רב אדא בר מתנה: \u0003אנא נמי במיתנא קא אמינא\u0004 \u0005[אני גם כן בחבל אני אומר]!\u0006 שאף אם משכו בחבל, מכל מקום רואים שיש בו קנין במשיכה בלא הגבהה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אני התכוונתי לומר שמדובר במשנה זו \u0003במידי דבעי מיתנא\u0004 \u0005[בדבר שצריך חבל],\u0006 כלומר, בכיס גדול כזה, שאי אפשר להגביה אותו אלא למושכו בחבל.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003ברשות מוכר\u0004 — \u0003לא קנה עד שיגביהנה, או עד שיוציאנה מרשותו; אלמא\u0004 \u0005[מכאן יוצא]\u0006 כי \u0003מידי דבר\u0004 \u0005[דבר ש\u0006הוא \u0005בן]\u0006 \u0003הגבהה, אי בעי\u0004 \u0005[אם רוצה]\u0006 \u0003בהגבהה קני ליה\u0004 \u0005[קונה אותו],\u0006 \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 \u0003במשיכה קני ליה\u0004 \u0005[קונה אותו]!\u0006 \u0003אמר רב נחמן בר יצחק:\u0004 אין להוכיח מכאן, שאפשר לומר כי \u0003לצדדין קתני\u0004 \u0005[שנה],\u0006 שאין כאן מתן שתי אפשרויות באותו דבר עצמו, אלא בשני מקרים שונים: \u0003מידי דבר\u0004 \u0005[דבר ש\u0006הוא \u0005בן]\u0006 \u0003הגבהה\u0004 — קונה אותו \u0003בהגבהה, מידי דבר\u0004 \u0005[דבר ש\u0006הוא \u0005בן]\u0006 \u0003משיכה\u0004 — קונה אותו \u0003במשיכה.\u0004"],["ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003המוכר פירות לחבירו, משך ולא מדד\u0004 — \u0003קני\u0004 \u0005[קונה];\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003פירות\u0004 ש\u0003בני הגבהה נינהו\u0004 \u0005[הם],\u0006 \u0003וקתני דקני\u0004 \u0005[ושנה שקונה]\u0006 \u0003במשיכה!\u0004","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשליפי רברבי\u0004 \u0005[בחבילות גדולות]\u0006 שמפני גודלן אין נהוג להגביהן, אלא מושכים אותן ממקום למקום. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בחבילות גדולות דווקא, ודווקא משום כך הפירות נקנים במשיכה, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003הלוקח\u0004 (קונה) \u0003פשתן מחבירו\u0004 — \u0003לא קנה עד שיטלטלנו ממקום זה למקום אחר,\u0004 שאינו נקנה במשיכה אלא בהגבהה בלבד, \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003פשתן בשליפי רברבי מי\u0004 \u0005[בחבילות גדולות האם]\u0006 \u0003לא עבדי\u0004 \u0005[עושים]?\u0006 ומשיבים: כן, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פשתן\u0004 מפירות, שאין נהוג לאורזו בחבילות גדולות, משום \u0003דמשתמיט\u0004 \u0005[ש\u0006הוא \u0005נשמט]\u0006 ממקומו אם אורזים אותו כך, אלא בחבילות קטנות, ולכן דרכו בהגבהה דווקא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, ממה ששנינו: \u0003בהמה גסה נקנית במסירה,\u0004 שכאשר המוכר מוסר את רצועתה לקונה — הריהי נקנית בכך. \u0003והדקה\u0004 — \u0003בהגבהה,\u0004 אלו \u0003דברי ר' מאיר ור' שמעון בן אלעזר. וחכמים אומרים: בהמה דקה\u0004 — \u0003במשיכה. והא\u0004 \u0005[והרי]\u0006 \u0003בהמה דקה דבר\u0004 \u0005[שבת]\u0006 \u0003הגבהה היא, וקתני דקני\u0004 \u0005[ושנה שקונה]\u0006 \u0003במשיכה!\u0004 ודחה רב אשי: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בהמה, דסרכא\u0004 \u0005[ש\u0006היא \u0005נאחזת\u0006 בקרקע\u0005]\u0006 ולכן קשה להגביה אותה, והדרך הרגילה היא למושכה אליו.","ובנושא אחר של מכירה, \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שאם אמר המוכר לקונה \u0003\"כור\u0004 (מידת נפח, שלושים סאים) של תבואה \u0003ב\u0004מחיר \u0003שלשים\u0004 סלעים כסף \u0003אני מוכר לך\"\u0004 — \u0003יכול\u0004 המוכר \u0003לחזור בו\u0004 כל זמן שלא נתמלאה המידה, \u0003אפילו בסאה האחרונה,\u0004 שלא מכר אלא כור שלם במדוייק; אבל אם אמר: \u0003\"כור בשלשים,\u0004 כל \u0003סאה בסלע\u0004 \u0003אני מוכר לך\"\u0004 אף שנתחרט באמצע — \u0003ראשון ראשון,\u0004 כלומר, כל סאה וסאה שמדד — \u0003קנה,\u0004 שהרי מכר כל סאה לעצמה.","על כך מקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן המשנה ששנינו בה: \u0003אם היתה מדה של אחד מהן\u0004 — \u0003ראשון ראשון קנה,\u0004 ומלשון כללית זו משמע: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא נתמלאה המדה!\u0004","ודוחים: במשנה מדובר \u0003כגון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר: \u0003\"הין\u0004 (מידת לח, שנים עשר לוג) \u0003בשנים עשר סלעים,\u0004 כל \u0003לוג בסלע אני מוכר לך\", וכ\u0004מו ש\u0003אמר רב כהנא: שנתות\u0004 (סימנים למדידה) \u0003היו ב\u0004מידת ה\u0003הין\u0004 שבמקדש, לצורך הנסכים השונים שהוקרבו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003שנתות היו במדות,\u0004 ולכן ראשון ראשון שהגיע למידת לוג אחד או שניים לפי השנתות — קנה, שהרי זה כמוכר סאה סאה לעצמה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003השוכר את הפועל\u0004 בזמן החורף או באביב \u0003לעשות עמו לגורן היום בדינר,\u0004 שבכל יום יהיה שכרו דינר אחד,"],["\u0003ול\u0004מלאכה זו בזמן ה\u0003גורן יפה\u0004 (שווה) השכר הוא \u0003סלע\u0004 (ארבעה דינרים) ליום — \u0003אסור להנות הימנו,\u0004 כלומר, אסור שיעבוד הפועל עמו באופן זה, משום שהוא כעין ריבית, שהפועל משיב לבעלים בעבודה יקרה יותר תמורת הכסף הניתן לו מוקדם יותר. \u0003אבל אם שכרו\u0004 כבר \u0003מהיום\u0004 לעבוד עבורו \u0003בדינר ליום\u0004 למשך זמן ממושך, עד ימות הגורן, אף על פי ש\u0003לגורן\u0004 יהא שכרו \u0003יפה סלע\u0004 — \u0003מותר.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כמו שאמרו רב ושמואל, ש\u0003\"כור בשלשים, סאה בסלע אני מוכר לך\"\u0004 — \u0003ראשון ראשון קנה,\u0004 שכל סאה נקנית לעצמה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כששכרו מהיום, נאמר: \u0003קמא קמא מיפסק פסק\u0004 \u0005[ראשון ראשון פוסק\u0006 הוא\u0005],\u0006 כלומר, אין זה תשלום אחד גדול, שהרי קוצב לו שכר לכל יום בנפרד, ונמצא איפוא שהוא כמשלם ריבית עבור הקדמת התשלום, \u0003ואסור להנות הימנו\u0004 (ממנו), ולפיכך מה ששנו בברייתא \u0003\"מ\u0004 היום ב\u0003דינר ליום ולגורן יפה סלע\u0004 — \u0003מותר, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא אגר\u0004 \u0005[והרי שכר]\u0006 \u0003\"נטר\u0004 \u0005[המתן]\u0006 \u0003לי\" הוא!\u0004","\u0003אמר רבא: ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 ש\u0003זלזולי\u0004 \u0005[לזלזל]\u0006 \u0003בשכירות מי אסיר\u0004 \u0005[האם אסור]?\u0006 האם אדם אינו רשאי לזלזל בשכר עבודתו ולקבל פחות כאשר הוא רוצה להבטיח לעצמו עבודה? ואם כן, אין כאן בעצם איסור ריבית כלל! ושואלים: אם אין בכך איסור ריבית, \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה בתחילה,\u0006 כשלא אמר \"מהיום\", שאסור הדבר, \u0005ומה שונה בסוף]?\u0006","ומשיבים: \u0003רישא דלא קא עביד בהדיה מהשתא\u0004 \u0005[בתחילה,\u0006 כיון \u0005שאינו עובד איתו מעכשיו]\u0006 \u0003מיחזי כי אגר\u0004 \u0005[נראה\u0006 הדבר \u0005כמו שכר]\u0006 \u0003\"נטר\u0004 \u0005[המתן]\u0006 \u0003לי\",\u0004 \u0003סיפא דקא עביד בהדיה מהשתא, לא מיחזי כי \"אגר נטר\u0004 \u0005[בסוף,\u0006 כיון \u0005שהוא עובד אצלו מעכשיו, אינו נראה כמו שכר המתן]\u0006 \u0003לי\".\u0004","שנינו במשנה ש\u0003אם היה\u0004 הפשתן \u0003מחובר בקרקע ותלש כל שהוא\u0004 — \u0003קנה.\u0004 ושואלים: \u0003משום\u0004 ש\u0003תלש כל שהוא קנה?\u0004 הרי לא עשה מעשה קנין בכל הפשתן, וכיצד קונהו? \u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דאמר ליה\u0004 \u0005[שאמר לו]\u0006 המוכר: \u0003לך, יפה\u0004 (נקה) \u0003לך קרקע כל שהוא, ו\u0004בכך \u0003קני כל מה שעליה,\u0004 שעל ידי עבודתו בתלישת הפשתן הוא נחשב כשוכר את הקרקע, ואגב כך קונה כל מה שעליה.","\u0003המוכר\u0004 דברי מאכל ומשקה, כגון: \u0003יין ושמן לחבירו\u0004 ומחירם ידוע, \u0003והוקרו או שהוזלו\u0004 במחירם, ורוצה אחד מהם לחזור בו מן המכירה, \u0003אם\u0004 ההתייקרות או ההוזלה היו \u0003עד שלא\u0004 (טרם) \u0003נתמלאת המדה\u0004 — הרי הסחורה עדיין שייכת \u0003למוכר\u0004 ויכול לחזור בו אם הוא רוצה בכך. ואילו \u0003משנתמלאת המדה\u0004 — הריהי שייכת כבר \u0003ללוקח\u0004 ואין המוכר יכול לחזור בו. \u0003ואם היה סרסור\u0004 (מתווך) \u0003ביניהן,\u0004 אם \u0003נשברה החבית\u0004 באמצע — \u0003נשברה לסרסור\u0004 והוא חייב באחריותה, וישלם.","\u0003ו\u0004הלכה נוספת בענייני מכירה: כל המוכר יין ושמן וכיוצא בהם \u0003חייב להטיף לו\u0004 לקונה \u0003שלש טיפין\u0004 נוספות מתוך המידה לאחר עירוי השמן. ולאחר שהטיף שלש טיפות אם \u0003הרכינה\u0004 את החבית על צידה \u0003ומיצית,\u0004 שנתמצה עוד מעט שמן בפנים — \u0003הרי הוא של\u0004 ה\u0003מוכר\u0004 ואינו צריך לתת זאת לקונה. \u0003והחנווני\u0004 שעיסוקו בכך \u0003אינו חייב להטיף שלש טיפין\u0004 משום שהוא טרוד ומוכר הרבה ואין לו זמן לעסוק בכך. \u0003ר' יהודה אומר:\u0004 \u0003ערב שבת עם חשכה\u0004 שאז הכל טרודים וממהרים — \u0003פטור\u0004 מלהטיף שלוש טיפות אלה.","ומבררים את דין המשנה במידה, אם נתמלאת או לא, \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003מדה\u0004 שמודדים בה, \u0003דמאן\u0004 \u0005[של מי]\u0006 היא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003מדה\u0004 של ה\u0003לוקח\u0004 היא, מדוע \u0003עד שלא נתמלאת\u0004 ה\u0003מדה\u0004 — \u0003למוכר?\u0004 הלא ה\u0003מדה\u0004 של ה\u0003לוקח היא,\u0004 וקנה כל מה שנכנס בתוך כליו, גם כאשר לא נתמלאו! \u0003ואלא\u0004 תאמר שהיא \u0003מדה\u0004 של ה\u0003מוכר,\u0004 אם כן \u0003משנתמלאת\u0004 ה\u0003מדה\u0004 מדוע מה שבתוכה נקנה \u0003ללוקח?\u0004 הלא \u0003מדה\u0004 של ה\u0003מוכר היא\u0004 ועדיין לא נכנס הדבר לרשותו או לכליו של הלוקח!","\u0003אמר ר' אלעא:\u0004 מדובר פה \u0003במדת סרסור,\u0004 שהמתווך ביניהם, הוא בעל המידה, ואינה שייכת לא למוכר ולא לקונה. אלא שהוא משאילה למוכר על מנת למדוד בה, ומשעה שנתמלאת — הרי זה לקונה, כדי שיעביר מה שיש בה לכליו שלו. ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה בסוף\u0006 בהמשך המשנה\u0005]:\u0006 \u0003ואם היה סרסור ביניהם, נשברה החבית\u0004 — \u0003נשברה לסרסור, מכלל\u0004 הדבר אתה למד \u0003דרישא לאו\u0004 \u0005[שבתחילה לא]\u0006 \u0003בסרסור עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 ומשיבים: \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר ב\u0003מדה\u0004 של סרסור \u0003בלא\u0004 ה\u0003סרסור\u0004 עצמו, \u0003סיפא\u0004 \u0005[סופה]\u0006 \u0003בסרסור עצמו\u0004 שהיה עימם בשעת המכירה, ולכן האחריות מוטלת עליו.","שנינו במשנה שאם \u0003הרכינה\u0004 את החבית על צידה \u0003ומיצית\u0004 — \u0003הרי הוא של מוכר.\u0004 מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' אלעזר\u0004 מבבל לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003זעירי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי כאן\u0004 ה\u0003תנא\u0004 \u0005[שונה משניות]\u0006 \u0003דאתנייה\u0004 \u0005[ששנה לו]\u0006 \u0003רב\u0004 הלכה זו לענין \u0003מדות?\u0004 לפי שרצונו לברר עמו ענין קשה בהלכה זו. \u0003אחוייה\u0004 \u0005[הראה לו]\u0006 את \u0003רב יצחק בר אבדימי. אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק בר אבדימי: \u0003מאי קא קשיא\u0004 \u0005[מה קשה]\u0006 \u0003לך\u0004 בהלכה זו? אמר לו: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הרכינה ומיצית\u0004 — \u0003הרי הוא של מוכר,\u0004"],["\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שמי שמערה שמן או יין של תרומה מכלי אחד לכלי שני, \u0003הרכינה ומיצה\u0004 — \u0003הרי זו תרומה\u0004 הניתנת לכהן! משמע שאף הדברים שמתמצים בשולי החבית שייכים למקבל. ומפני מה אין אומרים כן גם במשנתנו, שיהא המיצוי של הקונה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על משנתנו מהו טעמה, שכן \u0003אמר ר' אבהו:\u0004 זה ששנינו שמה שנתמצה שייך למוכר \u0003משום יאוש בעלים נגעו בה,\u0004 שהקונים מתייאשים ומוותרים על כמות קטנה זו. אבל בתרומה, כיון שהיא דבר של איסור אין שייך בזה יאוש בעלים, וכל מה שהערה תרומה הוא.","שנינו במשנה ש\u0003החנווני אינו חייב להטיף\u0004 שלוש טיפין, ור' יהודה אומר: ערב שבת עם חשיכה — פטור. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' יהודה ארישא קאי ולקולא\u0004 \u0005[על ראשה\u0006 של המשנה הוא \u0005עומד,\u0006 מתייחס, \u0005ולהקל\u0006 בא\u0005],\u0006 שכנגד האמור במשנה שכל אדם חייב להטיף שלוש טיפות, הוא מוסיף שבערב שבת פטור. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אסיפא קאי ולחומרא\u0004 \u0005[על סופה\u0006 הוא \u0005עומד,\u0006 מתייחס, \u0005ולהחמיר\u0006 בא\u0005],\u0006 שאמרו שחנווני פטור, ובא ר' יהודה לומר שרק בערב שבת הוא פטור?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: ערב שבת עם חשכה\u0004 — \u0003חנווני פטור, מפני שחנווני טרוד,\u0004 משמע שהוא מתייחס לסופה של המשנה, והוא פוטר את החנווני רק במקרה זה.","\u0003השולח את בנו אצל חנווני ופונדיון\u0004 (מטבע ששוויו שני איסרים) \u0003בידו, ומדד לו באיסר\u0004 אחד \u0003שמן, ונתן לו את האיסר\u0004 השני כעודף, אם \u0003שבר\u0004 הילד \u0003את הצלוחית ו\u0004כן אם \u0003אבד את האיסר\u0004 — \u0003חנווני חייב,\u0004 שהרי נתן אותה למי שאינו בן דעת. \u0003ר' יהודה פוטר,\u0004 שהוא אומר \u0003שעל מנת כן שלחו\u0004 אביו, וקיבל על עצמו האב את הסיכון של שבירה ואבידה. \u0003ומודים חכמים לר' יהודה, בזמן שהצלוחית ביד התינוק ומדד\u0004 ה\u0003חנווני לתוכה\u0004 — \u0003שחנווני פטור\u0004 אם נשברה הצלוחית ביד התינוק.","ומבררים את דין משנתנו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003באיסר ושמן\u0004 — אפשר לומר כי \u0003בהא פליגי\u0004 \u0005[ב\u0006ענין \u0005זה חלוקים\u0006 הם\u0005],\u0006 \u0003דרבנן סברי\u0004 \u0005[שהחכמים סבורים]\u0006 כי כדי \u0003לאודועי שדריה\u0004 \u0005[להודיע לו\u0006 לחנווני \u0005שלחו]\u0006 אבי התינוק את בנו, להודיע שהוא זקוק לשמן, אבל הוא לא התכוון בכך שיתן את השמן בידו, ולכן אם נתן לו — נתחייב החנווני באחריות. \u0003ור' יהודה סבר\u0004 \u0005[סבור]\u0006 כי כדי \u0003לשדורי ליה שדריה\u0004 \u0005[לשלוח לו שלחו]\u0006 שימסור החנווני את השמן לתינוק, ולכן פטור החנווני. \u0003אלא\u0004 אם \u0003שבר\u0004 התינוק את ה\u0003צלוחית\u0004 מדוע יתחייב בה החנווני לדעת חכמים? והלא \u0003אבדה מדעת היא\u0004 מצד האב, שהרי הוא זה שמסר בתחילה את הצלוחית ביד התינוק, שאינו יודע לשמור כראוי מה שבידו!","\u0003אמר רב הושעיא: הכא\u0004 \u0005[כאן]\u0006 \u0003בבעל הבית מוכר צלוחיות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ששולח את בנו לחנווני ובידו צלוחית זו, שמא ירצה החנווני לקנותה, \u0003וכגון שנטלה חנווני\u0004 את הצלוחית מיד התינוק \u0003על מנת לבקרה\u0004 (לבודקה אם טובה היא), \u0003וכ\u0004מו שאמר \u0003שמואל,\u0004 ש\u0003אמר\u0004 \u0003שמואל: הנוטל כלי מן האומן\u0004 (בעל מלאכה) \u0003על מנת לבקרו\u0004 (לבודקו), שאם ייראה לו טוב — יקננו מיד, \u0003ונאנס\u0004 נשבר הכלי באונס כשהוא \u0003בידו\u0004 — \u0003חייב\u0004 לשלם לאומן מחיר הכלי, משום שאחריותו עליו, כדין שואל.","על הסבר זה מקשים: ואם כן, \u0003לימא\u0004 \u0005[האם לומר],\u0006 כי הלכה זו של \u0003שמואל תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004 שהרי ר' יהודה פוטר, ומשמע לפיכך שאינו סבור כשמואל! \u0003אלא\u0004 יש לחזור מתירוץ זה ולפרש כך: \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בחנווני מוכר צלוחיות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהאב שלח את בנו לקנות מהחנווני צלוחית ובה שמן. \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו]\u0006 כפי שהוסברו הדברים מתחילה, שלדעתו נשלח התינוק אל החנווני על מנת שישלח בידו, \u0003ו\u0004כן \u0003רבנן\u0004 \u0005[חכמים]\u0006 הולכים לפי מה שהוסבר \u0003לטעמייהו\u0004 \u0005[לטעמם]\u0006 שהאב שלח את בנו להודיעו, ואינו רשאי ליתן בידו דבר.","ושואלים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 ששנינו: \u0003מודים חכמים לר' יהודה, בזמן שהצלוחית ביד התינוק ומדד חנווני לתוכה\u0004 — \u0003שחנווני פטור;\u0004 ומדוע יודו חכמים בכך? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כי \u0003לאודועי שדריה\u0004 \u0005[להודיע לו שלחו],\u0006 ולא נתכוון שיתן החנווני דבר ביד התינוק! \u0003אלא\u0004 יש לחזור אף מתירוץ זה ולפרש כך: \u0003אביי בר אבין ור' חנינא בר אבין דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 —"],["\u0003כגון שנטלה\u0004 החנווני את הצלוחית מיד התינוק על מנת \u0003למוד\u0004 (למדוד) \u0003בה\u0004 עבור הקונה, וכיון שנטלה בידו פעם אחת — נתחייב באונסין. \u0003וכ\u0004דברי \u0003רבה,\u0004 ש\u0003אמר רבה:\u0004 המוצא בהמה שאבדה, הלכה היא שאף במקרה שפטור הוא מלטפל בה להשיבה לבעליה (כגון זקן שאינו לפי כבודו), מכל מקום אם \u0003הכישה\u0004 (היכה את הבהמה) כדי להטותה לדרך — \u0003נתחייב בה\u0004 לטפל בהשבתה, שעצם הדבר שעשה בה מעשה מטיל עליו האחריות להשיבה לבעליה. ולכן אף כאן חייב החנווני, לדעת חכמים, על הצלוחית שנשברה.","ומקשים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר רבה\u0004 את דבריו רק \u0003בבעלי חיים,\u0004 שיש טעם לדבר, \u0003דאנקטינהו ניגרא ברייתא\u0004 \u0005[שלימד אותם פסיעות חיצוניות],\u0006 כלומר, גרם שיצאו ויטו עוד יותר מדרכם. ואולם, \u0003כי האי גונא מי אמר\u0004 \u0005[כגון זה,\u0006 בצלוחית, \u0005האם אמר]?\u0006 הרי נטילת הצלוחית אינה גורמת יותר לשבירתה מכפי שהיה בתחילה!","\u0003אלא\u0004 יש לחזור אף מתירוץ זה ו\u0003אמר רבא: אני וארי שבחבורה\u0004 (כלומר, אדם גדול שהיה עמנו) \u0003תרגימנוה\u0004 \u0005[הסברנוה],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]\u0006 אדם גדול זה? \u0003ר' זירא,\u0004 וכך הסברנו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנטלה\u0004 החנווני לצלוחית זו מיד התינוק על מנת \u0003למוד בה לאחרים,\u0004 ואין בעל הצלוחית, אבי התינוק, יודע על כך.","\u0003וב\u0004ענין \u0003שואל שלא מדעת קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 ר' יהודה וחכמים במשנתנו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]\u0006 שדינו ככל \u0003שואל הוי\u0004 \u0005[הוא],\u0006 וכיון שהחזיר לתינוק — שוב אינו אחראי על הצלוחית. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 שואל שלא מדעת \u0003גזלן הוי\u0004 \u0005[הוא]\u0006 וחייב בהשבה גמורה לבעלים עצמם, ולכן חייב על הצלוחית שנשברה בידי התינוק קודם שתגיע לידי אביו.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו קודם, \u0003אמר שמואל: הנוטל כלי מן האומן לבקרו ונאנס בידו\u0004 — \u0003חייב.\u0004 מסבירים: \u0003והני מילי הוא\u0004 — \u0003דקיצי דמיה\u0004 \u0005[ודברים אלה\u0006 אמורים רק באופן \u0005שקצובים דמיו]\u0006 של הכלי, שאפשר לומר שכאשר נטל את הכלי ואינו חסר לקנייתו אלא בדיקה, הרי זה כנוטל אותו לקנותו, אלא אם כן יתברר שאין הכלי טוב.","מסופר: \u0003ההוא גברא דעל לבי טבחא, אגבה אטמא דבישרא\u0004 \u0005[אדם אחד שנכנס לבית הקצב\u0006 כדי לקנות בשר, ו\u0005הגביה\u0006 בידו \u0005ירך\u0006 מן \u0005הבשר]\u0006 כדי לבודקה אם ראויה היא, \u0003בהדי דקא אגבה\u0004 \u0005[\u0006ו\u0005בתוך שהיה מגביה אותה]\u0006 \u0003אתא פרשא מרמא מיניה\u0004 \u0005[בא פרש\u0006 ו\u0005חטף\u0006 אותה \u0005ממנו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הקונה \u0005לפני]\u0006 \u0003רב יימר, חייביה לשלומי דמיה\u0004 \u0005[חייב אותו לשלם\u0006 את \u0005דמיה]\u0006 למוכר הבשר, לפי שהגביהה ומרשותו נלקחה. ומעירים שוב: \u0003והני מילי הוא\u0004 — \u0003דקיצי דמיה\u0004 \u0005[ודברים אלה\u0006 אמורים במקום \u0005שקצובים דמיה]\u0006 של ירך כזו, שלקיחתה ביד הרי היא כגמר המיקח.","ועוד מסופר בענין זה: \u0003ההוא גברא דאייתי קארי\u0004 \u0005[אדם אחד הביא דלעות]\u0006 \u0003ל\u0004עיר \u0003פום נהרא,\u0004 \u0003אתו כולי עלמא שקול קרא קרא\u0004 \u0005[באו הכל\u0006 ו\u0005לקחו דלעת דלעת]\u0006 כדי לקנותן, ועדיין לא שילמו. אותו אדם, כיון שלא ידע ממי לדרוש את כספו, כעס ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הרי הן מוקדשין לשמים,\u0004 שלא יוכלו ליהנות מן הדלעות שלקחו.","\u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב כהנא\u0004 לשאול מה דינן של הדלעות הללו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 אין ממש בדבריו, משום ש\u0003אין אדם מקדיש דבר שאינו שלו,\u0004 והדלעות הללו שנטלו בידם כבר אינן שלו. ומעירים שוב: \u0003והני מילי הוא\u0004 — \u0003דקיצי דמייהו\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שקצובים דמיהם]\u0006 והלוקח מן הדלעות כקונה הוא, \u0003אבל\u0004 אם \u0003לא קיצי דמייהו\u0004 \u0005[קצובים דמיהם]\u0006 — \u0003ברשות מרייהו קיימי\u0004 \u0005[בעליהם,\u0006 המוכר, הם \u0005עומדים]\u0006 \u0003ושפיר אקדיש\u0004 \u0005[ויפה הקדיש].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלוקח\u0004 (קונה) \u0003ירק מן השוק,\u0004 והמוכר אינו נאמן על מעשרות, ולכן הקונה ממנו צריך לעשר את הירק כאשר יגיעו לידו, \u0003ובירר\u0004 בין הירקות הגרועים והטובים, \u0003והניח\u0004 בצד טובים שבירקות, \u0003אפילו\u0004 עשה זאת \u0003כל היום כולו\u0004 ועדיין לא גמר בדעתו לקנותם — \u0003לא קנה ולא נתחייב במעשר.\u0004","אבל אם \u0003גמר בלבו לקנותו\u0004 — \u0003קנה ונתחייב במעשר;\u0004 ומעתה, מה יעשה? \u0003להחזירו\u0004 למוכר כמות שהוא, \u0003אי אפשר\u0004 — \u0003שכבר נתחייב במעשר. ולעשרו\u0004 ולתת המעשר למי שזכאי לו, גם כן \u0003אי אפשר\u0004 — \u0003שכבר מפחיתן בדמים, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יעשה? \u0003מעשרו\u0004 ונותן המעשר למי שצריך לקבלו, \u0003ונותן לו\u0004 למוכר \u0003דמי מעשר\u0004 שחיסר ממנו.","ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003משום\u0004 ש\u0003גמר בלבו לקנות, קנה ונתחייב במעשר?\u0004 הרי לא אמר דבר, ולא עשה מעשה קנין! \u0003אמר רב הושעיא: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004קונה שהוא \u0003ירא שמים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003כגון רב ספרא,\u0004 ש\u0003קיים בנפשיה\u0004 \u0005[בעצמו]\u0006 את הפסוק \u0003\"ודבר אמת בלבבו\"\u0004 (תהלים טו, ב), שהיה מחייב עצמו בענייני מיקח וממכר רק לפי הסכמתו הפנימית, גם כאשר לא אמר ולא עשה דבר, ואדם כזה קונה ומתחייב במעשר משעה שגומר בלבו לקנות.","\u0003הסיטון\u0004 (מי שקונה כמויות גדולות של דברי מאכל ומשקה ומוכרם לחנוונים) \u0003מקנח\u0004 (מנקה) \u0003מדותיו,\u0004 את כלי המדידה שהוא מודד בהן משקים, כגון יין ושמן, \u0003אחד ל\u0004כל \u0003שלשים יום,\u0004 מפני ששיירי הדברים שהוא מוכר נדבקים בכלי המדידה ומפחיתים את קיבולם. \u0003ובעל הבית,\u0004 המוכר רק מזמן לזמן — מקנח מידותיו \u0003אחד לשנים עשר חדש. רבן שמעון בן גמליאל אומר: חילוף הדברים,\u0004 שהמוכר תדיר אין השיירים נדבקים במידותיו, ולכן די לסיטון בקינוח פעם בשנים עשר חודש, ואילו המוכר לעתים רחוקות השיירים נדבקים בהן ומפחיתים את קיבולן, ולכן צריך בעל הבית לקנח אחת לשלושים יום.","\u0003חנווני\u0004 המוכר הרבה בכמויות קטנות, \u0003מקנח מדותיו פעמים בשבת\u0004 (בשבוע) \u0003וממחה\u0004 (מנקה) \u0003משקלותיו פעם אחת בשבת, ומקנח מאזנים על כל משקל ומשקל\u0004 שהוא שוקל, שמא דבק במאזניים משהו ממה שמוכר, ומכביד את המאזניים שלא כדין. \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 שצריך לקנח — \u0003ב\u0004מוכר דבר \u0003לח\u0004 שנדבק במידות ובמשקלות, \u0003אבל ב\u0004מוכר דבר \u0003יבש\u0004 שאינו נדבק — \u0003אינו צריך\u0004 לקנח."],["\u0003וחייב\u0004 המוכר להוסיף משלו ו\u0003להכריע\u0004 (להטות) \u0003לו\u0004 את המאזניים \u0003טפח,\u0004 שתהא אותה כף שבה מצוי הדבר הנמכר נמוכה טפח מהכף השניה, שבה אבן המשקל. \u0003היה שוקל לו עין בעין,\u0004 כלומר, בדיוק ובצמצום בלי הכרעה — \u0003נותן לו גירומין\u0004 (תוספת) במקום ההכרעה הזו, ושיעורה הוא: \u0003אחד לעשרה\u0004 — \u0003בלח, ואחד לעשרים\u0004 — \u0003ביבש,\u0004 כאשר יבואר עניינו בגמרא.","ועוד בענין מדידה, \u0003מקום שנהגו למוד ב\u0004מידה \u0003דקה,\u0004 כלומר, במידות קטנות — \u0003לא ימוד ב\u0004מידה \u0003גסה,\u0004 כלומר, במידה גדולה, בפעם אחת. וכן להיפך, מקום שנהגו למדוד \u0003ב\u0004מידה \u0003גסה\u0004 ובפעם אחת — \u0003לא ימוד ב\u0004מידה \u0003דקה\u0004 מספר פעמים. מקום שנהגו \u0003למחוק\u0004 את המידה, כלומר, ליישר את הדברים שנמדדים בדיוק לפי גובה שפת הכלי — \u0003לא יגדוש\u0004 את הכלי מעל גובה שפתו. במקום שנהגו \u0003לגדוש\u0004 — \u0003לא ימחוק.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה מקור הלכה זו שיש להכריע? \u0003אמר ריש לקיש,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אבן שלמה וצדק\"\u0004 (דברים כה, טו), לומר: \u0003צדק משלך,\u0004 כלומר, הוסף משלך המוכר \u0003ותן לו\u0004 לקונה. ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה,\u0006 המשכה של המשנה\u0005]:\u0006 \u0003היה שוקל לו עין בעין\u0004 — \u0003נותן לו גירומין, ואי\u0004 \u0005[ואם]\u0006 \u0003הכרעה\u0004 במשקל הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003היכי יהיב ליה\u0004 \u0005[כיצד נותן לו]\u0006 בכלל מתחילה \u0003עין בעין?\u0004","\u0003אלא\u0004 יש לומר שדין זה של הכרעה אינו מן התורה, והלכה זו הנזכרת ב\u0003רישא\u0004 \u0005[ראשה\u0006 של המשנה\u0005]\u0006 בענין הכרעה מדברת \u0003במקום שנהגו\u0004 להכריע כף מאזניים. \u0003וכי איתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דברי \u0003ריש לקיש\u0004 — \u0003אסיפא איתמר\u0004 \u0005[על סופה,\u0006 המשכה של המשנה \u0005נאמר]:\u0006 \u0003היה שוקל לו עין בעין\u0004 — \u0003נותן לו גירומין,\u0004 ועל כל הענין נשאלת השאלה: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ריש לקיש,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וצדק\",\u0004 לומר: \u0003צדק משלך ותן לו.\u0004 ושואלים: \u0003וכמה\u0004 שיעורם של \u0003גירומין? אמר ר' אבא בר ממל אמר רב: אחד מעשרה בליטרא\u0004 (עשירית הליטרא) \u0003ב\u0004דבר \u0003לח ל\u0004כל \u0003עשרה ליטרין,\u0004 כלומר, אחד למאה.","שנינו במשנה שהגירומין הם \u0003אחד לעשרה בלח, ואחד לעשרים ביבש וכו'. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[כיצד\u0006 הוא \u0005אומר]?\u0006 האם הכוונה היא \u0003אחד מעשרה בלח לעשרה\u0004 מידות ה\u0003לח, ו\u0004באותו אופן יש להבין: \u0003אחד מעשרים ביבש לעשרים\u0004 מידות של ה\u0003יבש,\u0004 שהם אחד לארבע מאות. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אחד מעשרה לעשרה\u0004 של מידת \u0003לח, ו\u0004כן אחד מעשרה \u0003לעשרים\u0004 מידות של ה\u0003יבש,\u0004 שהם אחד ממאתים? שאלה זו לא נפתרה ועל כן ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ר' לוי: קשה עונשן של מדות\u0004 שמרמים בהן המוכרים, \u0003יותר מעונשן של עריות, שזה\u0004 בעריות \u0003נאמר בהן \"אל\"\u0004 (\"כל התועבות האל\". ויקרא יח, כו), \u0003וזה נאמר בהן \"אלה\"\u0004 (\"כי תועבת ה' אלקיך כל עושה אלה\". דברים כה, טז). \u0003ומאי\u0004 \u0005[ומה\u0006 ומנין\u0005]\u0006 \u0003משמע דהאי\u0004 \u0005[שזה]\u0006 הביטוי \u0003\"אל\"\u0004 דבר \u0003קשה הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת אילי הארץ לקח\"\u0004 (יחזקאל יז, יג), כלומר, החזקים והתקיפים.","ומקשים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עריות נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אלה\"\u0004 (\"ולא תעשו מכל התועבות האלה\". ויקרא יח, כו. \"כי כל אשר יעשה מכל התועבות האלה...\". יחזקאל יז, כט)! ומשיבים: \"אלה\" \u0003ההוא\u0004 שנאמר בעריות, לא להדגיש את חומרתן בא, אלא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מדות מ\u0004עונש \u0003כרת,\u0004 לומר שרק בעריות יש איסור כרת, ולא במידות.","ושואלים: \u0003ואלא\u0004 אם כן \u0003מאי עודפייהו\u0004 \u0005[מה יתרונן,\u0006 חומרתן\u0005],\u0006 ובמה עונשן של מידות קשה יותר משל עריות? ומשיבים: \u0003דהתם\u0004 \u0005[ששם]\u0006 בעריות \u0003אפשר\u0004 לחזור \u0003בתשובה, והכא\u0004 \u0005[וכאן]\u0006 במרמה במידות — \u0003לא אפשר\u0004 לחזור \u0003בתשובה\u0004 שהרי אינו יודע ממי לקח וכמה לקח. ולכן אינו יכול להחזיר.","\u0003ו\u0004עוד \u0003אמר ר' לוי: קשה\u0004 (חמור) \u0003גזל\u0004 שגוזל \u0003הדיוט,\u0004 כלומר, מאדם, \u0003יותר מגזל גבוה\u0004 (הקדש), \u0003שזה\u0004 בגזלן \u0003הקדים\u0004 הכתוב לשון \u0003\"חטא\" ל\u0004לשון \u0003\"מעילה\",\u0004 כאמור \"נפש כי תחטא ומעלה מעל בה' וכיחש בעמיתו\" (יחזקאל ה, כא), \u0003ו\u0004אילו ב\u0003זה\u0004 המועל בהקדש, \u0003הקדים\u0004 הכתוב לשון \u0003\"מעילה\" ל\u0004לשון \u0003\"חטא\",\u0004 כאמור \"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה'\" (יחזקאל ה, טו).","\u0003ו\u0004עוד \u0003אמר ר' לוי: בוא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם; הקדוש ברוך הוא ברך\u0004 את \u0003ישראל בעשרים ושתים\u0004 ברכות \u0003וקללן בשמנה,\u0004 כיצד? — \u0003ברכן בעשרים ושתים\u0004 — \u0003מ\"אם בחקתי\u0004 תלכו\u0003\"\u0004 (יחזקאל כו, ג) המתחיל באות א', \u0003עד\u0004 ב\u0003\"קוממיות\"\u0004 (יחזקאל כו, יג) הנגמר באות ת',","\u0003וקללן בשמונה\u0004 — \u0003מ\"ואם בחקתי תמאסו\"\u0004 (יחזקאל כו, טו) \u0003עד \"ואת חקתי געלה נפשם\"\u0004 (יחזקאל כו, מג); הרי שמונה אותיות (מו' של \"ואם\" עד מ' שב\"נפשם\"),","\u0003ואילו משה רבינו\u0004 שבשר ודם הוא, \u0003ברכן בשמונה וקללן בעשרים ושתים,\u0004 כיצד? \u0003ברכן בשמונה\u0004 —"],["\u0003מ\"והיה אם שמוע תשמע\"\u0004 (דברים כח, א) \u0003ועד \"לעבדם\"\u0004 (דברים כח, יד), \u0003וקללן בעשרים ושתים\u0004 — \u0003מ\"והיה אם לא תשמע\u0004 בקול ה'\u0003\"\u0004 (דברים כח, טו) \u0003עד \"ואין קנה\"\u0004 (דברים כח, סט).","שנינו במשנה: \u0003מקום שנהגו למוד\u0004 (למדוד) \u0003בגסה\u0004 אין מודדים במידה דקה (קטנה), למחוק — לא יגדוש, לגדוש — לא ימחוק. \u0003(סימן\u0004 להלכות הבאות: \u0003אין מעיינין ואין גודשין באגרדמין ובליטרא שלשה ועשר נפש משקלות ממחק עבה לא תעשו לא יעשה).\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין מוחקין\u0004 את המידות \u0003במקום ש\u0004נהגו להיות \u0003גודשין, ו\u0004כן ש\u0003אין גודשין במקום שמוחקין?\u0004 — \u0003תלמוד לומר: \"איפה שלמה\"\u0004 (דברים כה, טו), כפי שנחשבת האיפה שלמה באותו מקום, לא פחות ולא יותר, באופן שאין מקום להטעיה ולרמייה.","\u0003ומנין שאם אמר\u0004 המוכר: \u0003הריני מוחק במקום שגודשין, ו\u0004זאת כדי \u0003לפחות לו\u0004 לקונה \u0003מן הדמים\u0004 כנגד המחק הזה, \u0003ו\u0004כן אם אמר: \u0003הריני גודש במקום שמוחקין, ו\u0004זאת כדי \u0003להוסיף לו על הדמים, שאין שומעין לו?\u0004 — \u0003תלמוד לומר: \"איפה שלמה וצדק יהיה לך\"\u0004 (דברים כה, טו), שלנהוג במנהג המקום הוא מידת הצדק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין מעיינין,\u0004 שאין מאזנים את המאזניים ושוקלים בדיוק (עין בעין) \u0003במקום\u0004 בו המנהג הוא \u0003שמכריעין,\u0004 שמטים את כף המאזניים טפח לטובת הקונה, \u0003ו\u0004כן ש\u0003אין מכריעין במקום שמעיינין?\u0004 — \u0003תלמוד לומר: \"אבן שלמה\",\u0004 לומר שצריך המשקל (\"אבן\") להיות שלם כפי הנהוג באותו מקום, לא פחות ולא יותר (דברים כה, טו).","\u0003ומנין שאם אמר: הריני מעיין במקום שמכריעין, ו\u0004על דעת \u0003לפחות לו מן הדמים\u0004 כנגד מה שלא הכרעתי, או שאמר: \u0003הריני מכריע, במקום שמעיינין, ו\u0004על דעת \u0003להוסיף לו על הדמים, שאין שומעין לו?\u0004 — \u0003תלמוד לומר: \"אבן שלמה וצדק\"\u0004 (דברים כה, טו), לומר שמידת הצדק היא לנהוג כמנהג המקום.","\u0003אמר רב יהודה מסורא\u0004 בדרך הדרש על הפסוק \"לא יהיה לך בביתך איפה ואיפה\" (דברים כה, יד): \u0003\"לא יהיה לך בביתך\",\u0004 כלומר, שסופך להיות עני שאין לו דבר בביתו, ו\u0003מה טעם\u0004 הדבר? — \u0003משום\u0004 שעסקת במסחר באופן של \u0003\"איפה ואיפה\"\u0004 שאדם קונה בכלי גדול ומוכר בכלי קטן.","וכן על הכתוב \"לא יהיה לך בכיסך אבן גדולה ואבן קטנה\" (דברים כה, יג), \u0003\"לא יהיה לך בכיסך\",\u0004 \u0003מה טעם? —\u0004 \u0003משום \"אבן ואבן\". אבל\u0004 אם תנהג בדרך של \u0003\"אבן שלמה וצדק\"\u0004 — הרי אז \u0003\"יהיה לך\",\u0004 וכן \u0003איפה שלמה וצדק\u0004 — \u0003\"יהיה לך\"\u0004 (דברים כה, יג).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"(לא) יהיה לך\"\u0004 — \u0003מלמד שמעמידין\u0004 (ממנים) \u0003אגרדמין\u0004 (מפקחים על השוק) \u0003למדות,\u0004 שבודקים בשליחות בית הדין את דיוק המידות, ומדייקת הגמרא: \u0003ו\u0004אולם \u0003אין מעמידין אגרדמין לשערים,\u0004 לפקח על המחירים. מסופר: \u0003דבי נשיאה אוקימו\u0004 \u0005[בבית הנשיא העמידו]\u0006 \u0003אגרדמין בין למדות בין לשערים, אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל ל\u0004חכם \u0003קרנא\u0004 תלמידו, \u0003פוק תני להו\u0004 \u0005[צא ושנה להם]:\u0006 \u0003מעמידין אגרדמין למדות, ואין מעמידין אגרדמין לשערים.\u0004","\u0003נפק\u0004 \u0005[יצא]\u0006 קרנא ו\u0003דרש להו\u0004 \u0005[להם]:\u0006 \u0003מעמידין אגרדמין בין למדות בין לשערים.\u0004 נודע הדבר לשמואל, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מה שמך?\u0004 אמר לו: \u0003קרנא,\u0004 אמר לו שמואל: \u0003תיפוק ליה קרנא בעיניה\u0004 \u0005[תצא לו קרן בעיניו].\u0006 ואכן, \u0003נפקא ליה קרנא בעיניה\u0004 \u0005[יצאה לו קרן בעיניו],\u0006 כלומר, צמח לו גידול של בשר על עינו. ושואלים: \u0003ואיהו כמאן סבר\u0004 \u0005[והוא,\u0006 קרנא, \u0005כמי\u0006 היה \u0005סבור]\u0006 שכך שינה מדברי רבו? \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רמי בר חמא אמר ר' יצחק:\u0004 \u0003מעמידין אגרדמין בין למדות בין לשערים, מפני הרמאין\u0004 שמא יקטינו את המידות, או יורידו את המחיר ויפחיתו מטיב הסחורה.","ודנים בפרטי דינים הקשורים לדין משנתנו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה\u0004 הקונה \u0003מבקש ממנו\u0004 מהמוכר משקל \u0003ליטרא\u0004 של דבר מסויים — \u0003שוקל לו\u0004 במשקל של \u0003ליטרא.\u0004 היה מבקש ממנו \u0003חצי ליטרא\u0004 — \u0003שוקל לו חצי ליטרא.\u0004 מבקש \u0003רביע ליטרא\u0004 — \u0003שוקל לו רביע ליטרא.\u0004 ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 והרי פשוט הוא שכך יש לנהוג. ומסבירים: \u0003דמתקנינן מתקלי\u0004 \u0005[שמתקינים משקלות]\u0006 \u0003עד הכי\u0004 \u0005[כך],\u0006 עד מידת רבע ליטרא, ולא פחות מזה. ואם מבקש הקונה לשקול לו במועט מזה — אין שומעים לו.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה מבקש ממנו שלשה רבעי ליטרא,\u0004 ואין אבן משקל שגודלה שלושה רבעים, \u0003לא יאמר לו: שקול לי שלשה רבעי ליטרא אחת אחת,\u0004 רבע רבע לעצמו, ונמצא שמוסיף הכרע על כל רבע לעצמו, \u0003אלא שוקל ליטרא\u0004 מניח אבן משקל של ליטרא בכף מאזניים אחת, \u0003ומניח\u0004 אבן משקל של \u0003רביע ליטרא\u0004 בכף השניה \u0003עם הבשר\u0004 הנמכר,","כך ששוקל את שלושת רבעי הליטרא בבת אחת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה מבקש ממנו\u0004 סחורה במשקל \u0003עשר ליטרין, לא יאמר לו\u0004 הקונה: \u0003שקול לי אחת אחת והכריע\u0004 בכל שקילה, משום שבכל הכרע תמיד נוסף מעט, ויש בכך הפסד למוכר, \u0003אלא שוקל לו כולן בבת אחת, ונותן הכרע אחד לכולן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נפש מאזנים,\u0004 כלומר, החלק העליון שבו תלויים המאזניים \u0003תלויה באויר\u0004 רחוק מן התיקרה \u0003שלשה טפחים, ו\u0004כן צריך שתהיה \u0003גבוהה מן הארץ שלשה טפחים, וקנה\u0004 (שמשני צידיו תלויות כפות המאזניים) \u0003ומתנא\u0004 (החבל שבו תלויה כל כף) \u0003שלה שנים עשר טפחים. ו\u0004מאזניים \u0003של צמרים\u0004 (עושי צמר) \u0003ושל זגגין\u0004 (עושי זכוכית) — \u0003תלויה באויר שני טפחים, וגבוהה מן הארץ שני טפחים, וקנה ומתנא שלה תשעה טפחים. ו\u0004מאזניים","\u0003של חנווני ושל בעל הבית\u0004 — \u0003תלויה באויר טפח, וגבוהה מן הארץ טפח, וקנה ומתנא שלה ששה טפחים. ושל טורטני\u0004 מאזניים קטנות לכסף וזהב — \u0003תלויה באויר שלש אצבעות, וגבוהה מן הארץ שלש אצבעות,\u0004 וממשיך התנא: \u0003וקנה ומתנא שלה איני יודע.\u0004","ושואלים: הרי מנה פה את כל מיני המשקלות השונים לפי שימושיהם \u0003ואלא הך קמייתא דמאי\u0004 \u0005[זו הראשונה של מה]?\u0006 לאיזה דבר משמשים מאזניים גדולים אלה?"],["\u0003אמר רב פפא: דיגרומי\u0004 \u0005[של נפחים]\u0006 ששוקלים משקלות כבדים של מתכות.","\u0003אמר ר' מני בר פטיש: כדרך שאמרו לענין איסורן\u0004 של מאזניים, שאסור לשקול בהם אם אינם עשוים כפי האמור בברייתא, \u0003כך אמרו לענין טומאתן,\u0004 שאם לא עשאם באופן זה — אין אותם חלקים (הקנה, המתנא) מקבלים טומאה כחלק מן המאזניים.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה בהלכות טומאה: \u0003חוט\u0004 שבו תולים \u0003מאזנים של חנוני ושל בעלי בתים\u0004 — \u0003טפח,\u0004 כפי ששנינו אצלנו לענין איסורם! ומשיבים: אמנם לענין חוט שנינו, אבל \u0003קנה ומתנא שלה איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005],\u0006 ש\u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 לענין טומאה.","ועוד בענין התקנת משקלות \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עושין משקלות לא של בעץ\u0004 (בדיל) \u0003ולא של אבר\u0004 (עופרת), \u0003ולא של גיסטרון\u0004 (תערובת מתכות), \u0003ולא של שאר מיני מתכות,\u0004 משום שכל אלה נשחקים במשך הזמן, ונמצאים הקונים מפסידים כיון שמשלמים עבור משקל גדול יותר ממה שקיבלו בפועל. \u0003אבל עושה הוא של צונמא\u0004 (אבן קשה) \u0003ושל זכוכית.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עושין\u0004 את \u0003המחק\u0004 מעין סרגל שמוחקים בו את העודף שבכלי (כגון של קמח) \u0003של דלעת\u0004 — \u0003מפני שהוא קל\u0004 מדי ולא ימחוק יפה, ונמצא המוכר מפסיד, \u0003ולא של מתכת\u0004 — \u0003מפני שהוא מכביד\u0004 ומוחק יותר מן הראוי, ונמצא הקונה מפסיד, \u0003אבל עושהו של\u0004 עץ \u0003זית ושל אגוז, של שקמה ושל אשברוע\u0004 שכובדם ממוצע.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עושין את המחק צדו אחד עב וצדו אחד קצר\u0004 (צר), שאין המחיקה שווה בשני הצדדים. ו\u0003לא ימחוק בבת אחת\u0004 בפעם אחת ובמהירות, \u0003שהמוחק בבת אחת\u0004 — \u0003רע למוכר ויפה ללוקח,\u0004 שהוא מוחק פחות, \u0003ו\u0004מצד אחר \u0003לא ימחוק מעט מעט\u0004 פעמים רבות, משום \u0003ש\u0004דבר זה הוא \u0003רע ללוקח ויפה למוכר.\u0004","\u0003על כולן\u0004 על כל ההלכות הללו, \u0003אמר רבן יוחנן בן זכאי: אוי לי אם אומר, אוי לי אם לא אומר,\u0004 ומדוע? \u0003אם אומר\u0004 אותן — \u0003שמא ילמדו הרמאין\u0004 מתוך דברי הלכה אלה שיטות של רמאות שלא ידעו אותן קודם, \u0003ואם לא אומר\u0004 — \u0003שמא יאמרו הרמאין: אין תלמידי חכמים בקיאין במעשה ידינו. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם לבסוף \u0003אמרה\u0004 רבן יוחנן להלכה זו ברבים, \u0003או לא אמרה? אמר רב שמואל בר רב יצחק:\u0004 \u0003אמרה, ומהאי קרא\u0004 \u0005[ומתוך,\u0006 על סמך \u0005כתוב זה]\u0006 \u0003אמרה,\u0004 שנאמר: \u0003\"כי ישרים דרכי ה' וצדקים ילכו בם ופשעים יכשלו בם\"\u0004 (הושע יד, י).","ועוד בענייני משקלות \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"לא תעשו עול במשפט במדה במשקל ובמשורה\"\u0004 (ויקרא יט, לה), \u0003\"במדה\"\u0004 — \u0003זו מדידת קרקע,\u0004 וכיצד לא יעשה עול במדידת קרקע? \u0003שלא ימדוד לאחד בימות החמה\u0004 שאז החבל המשמש למדידה מתייבש ומתקצר, \u0003ולאחד בימות הגשמים\u0004 כשהחבל נרטב, ונעשה רפוי יותר ומתארך. \u0003\"במשקל\"\u0004 — \u0003שלא יטמין משקלותיו במלח\u0004 שמאכל את המשקלות ונמצא הקונה מפסיד. \u0003\"במשורה\"\u0004 — \u0003שלא ירתיח,\u0004 כלומר, שלא ישפוך מהר ויעשה קצף, ועל ידי כך ימכור פחות מן המידה.","ומעירים, \u0003וקל וחומר\u0004 הוא: \u0003ומה משורה שהיא\u0004 מידה של \u0003אחד משלשים וששה בלוג\u0004 — \u0003הקפידה עליו תורה\u0004 שלא ירמה בה, \u0003קל וחומר ל\u0004מידות גדולות כמו \u0003הין וחצי הין ושלישית ההין ורביעית ההין, ולוג וחצי לוג ורביעית\u0004 הלוג, \u0003וחצי תומן\u0004 (חצי שמינית) הלוג, \u0003ועוכלא\u0004 שהיא מידה קטנה יותר.","\u0003אמר רב יהודה אמר רב: אסור לאדם שישהה מדה חסרה או יתרה בתוך ביתו, ואפילו\u0004 אינו משתמש בה למדוד, אלא \u0003היא\u0004 משמשת לו רק כ\u0003עביט של מימי רגלים. אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא באתרא\u0004 \u0005[במקום]\u0006 ש\u0003לא חתימי\u0004 \u0005[חתומות]\u0006 המידות, כלומר, שאין חותם המלכות המאשר את תקינותן נמצא על גבי המידות, \u0003אבל באתרא דחתימי\u0004 \u0005[במקום שחתומות]\u0006 — \u0003אי לא חזי\u0004 \u0005[אם אין\u0006 הקונה \u0005רואה]\u0006 \u0003חתימה לא שקיל\u0004 \u0005[אינו לוקח]\u0006 ולכן יכול להשתמש בהן לצרכים אחרים, שהרי לא יטעו בהן הבריות. ומעירים: \u0003ובאתרא דלא חתימי נמי\u0004 \u0005[ובמקום שאינן חתומות גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאסור להשהות בבית, \u0003אלא\u0004 במקרה \u0003דלא מהנדסי\u0004 \u0005[שאין בודקים ומודדים\u0006 באותו מקום\u0005]\u0006 את כשרות המידות, \u0003אבל\u0004 אם \u0003מהנדסי\u0004 \u0005[בודקים ומודדים],\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","ומעירים: \u0003ולא היא\u0004 (ואין הדבר כן) ואסור להשהות בבית מידות בלתי נכונות בכל אופן, כי \u0003זימנין דמיקרי\u0004 \u0005[פעמים שמזדמן]\u0006 \u0003בין השמשות\u0004 כאשר הכל טרודים וממהרים, \u0003ומיקרי ושקיל\u0004 \u0005[ומזדמן\u0006 שהקונה \u0005לוקח]\u0006 אפילו במידה שאינה ראויה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לא ישהה אדם מדה חסרה או יתרה בתוך ביתו, ואפילו היא עביט של מימי רגלים, אבל עושה הוא\u0004 מידות במתכונת הקבועה להן: מידה של \u0003סאה,\u0004 של \u0003תרקב\u0004 (חצי סאה, שלושה קבים) או \u0003חצי תרקב\u0004 (קב וחצי), \u0003קב, וחצי קב, ורובע\u0004 הקב, \u0003ותומן\u0004 (שמינית הקב) \u0003וחצי תומן,\u0004"],["\u0003ועוכלא. וכמה היא עוכלא? אחד מחמשה ברביע\u0004 הקב. \u0003ובמדת הלח\u0004 — \u0003הוא עושה הין\u0004 (שנים עשר לוגים), \u0003וחצי הין\u0004 (ששה לוגים), \u0003ושלישית ההין\u0004 (ארבעה לוגים), \u0003ורביעית ההין\u0004 (שלושה לוגים), \u0003ולוג, וחצי לוג, ורביעית\u0004 הלוג, \u0003ושמינית\u0004 הלוג, \u0003ואחד משמונה בשמינית\u0004 הלוג, \u0003וזהו\u0004 שיעור \u0003קורטוב.\u0004","ושואלים: \u0003ולעביד נמי\u0004 \u0005[ויעשה גם כן]\u0006 מידה של \u0003קביים\u0004 (שני קבים)! ומשיבים: אין עושים כן, שמא \u0003אתי לאיחלופי\u0004 \u0005[יבוא להתחלף]\u0006 \u0003בתרקב\u0004 שהוא שלושה קבים. ומקשים: \u0003אלמא טעו אינשי תילתא\u0004 \u0005[מכאן\u0006 עולה כי \u0005טועים אנשים שליש]\u0006 במידה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזהו הטעם, \u0003קב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליעביד\u0004 \u0005[יעשה],\u0006 כיון שחוששים \u0003דאתי לאיחלופי\u0004 \u0005[שיבוא להתחלף]\u0006 \u0003בחצי תרקב\u0004 ששיעורו קב וחצי! \u0003אלא קביים היינו טעמא דלא עביד\u0004 \u0005[זהו הטעם שאין עושה]\u0006 — מחמת החשש \u0003דאתי לאיחלופי\u0004 \u0005[שיבוא להתחלף]\u0006 \u0003בחצי תרקב\u0004 שהוא קב וחצי.","ושואלים: \u0003אלמא טעי איניש ריבעא\u0004 \u0005[מכאן\u0006 ש\u0005טועים אנשים רבע]\u0006 במידה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003חצי תומן ועוכלא לא ליעביד\u0004 \u0005[יעשה],\u0006 שהרי חצי תומן הוא אחד משש עשרה בקב, ועוכלא הוא אחד מעשרים, וההבדל ביניהם קטן יותר, חמישית! \u0003אמר רב פפא: מדות קטנות בקיאי בהו אינשי\u0004 \u0005[בקיאים בהן אנשים]\u0006 ומבחינים בהבדל.","ושואלים: אם טועים ברבע, אם כן כיון שעושה מידת \u0003שלישית ההין\u0004 שהיא ארבעה לוגים, מידת \u0003רביעית ההין\u0004 שהיא של שלושה לוגים \u0003לא ליעביד\u0004 \u0005[יעשה]!\u0006 ומשיבים: \u0003כיון דהוו\u0004 \u0005[שהיו]\u0006 מידות אלה \u0003במקדש, לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006 ומקשים: \u0003במקדש נמי ליגזור\u0004 \u0005[גם כן שיגזרו]\u0006 שמא יחליפו גם שם את המידות! ומשיבים: \u0003כהנים זריזין הן\u0004 ומשתדלים הרבה בעבודתם, ואינם באים לידי טעות.","\u0003אמר שמואל: אין מוסיפין על המדות יותר משתות\u0004 (שישית), אם רוצים אנשי המקום לשנות את גודלם של כל המידות הנהוגות במקומם, ולהוסיף עליהן אחוז מסויים, \u0003ולא על המטבע\u0004 להעלות את ערכו \u0003יתר משתות, והמשתכר\u0004 במסחרו \u0003אל ישתכר יותר משתות.\u0004 ודנים בדברים האמורים: זה שאמרנו ש\u0003אין מוסיפין\u0004 \u0003על המדות יותר משתות,\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003משום\u0004 שיגרום הדבר ל\u0003אפקועי תרעא\u0004 \u0005[הפקעת שערים,\u0006 התייקרות המחירים בשוק\u0005]\u0006 — \u0003שתות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שהרי גם שם קיים אותו חשש!","\u0003אלא\u0004 תאמר כי הסיבה היא \u0003משום אונאה,\u0004 ש\u0003לא ליהוי\u0004 \u0005[יהא]\u0006 \u0003ביטול מקח,\u0004 כי עד שישית מחזיר את ההונאה, אבל המיקח קיים, אבל ביותר משישית — המיקח כולו בטל, ואין זה נכון לתקן דבר שמפני טעויות המצויות בזמן שינוי המידות יתבטלו מכירות רבות — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: כל דבר שבמדה ושבמשקל ושבמנין\u0004 — \u0003אפילו פחות מכדי אונאה חוזר,\u0004 וכאן מדובר בטעות במידה, בין המידה הישנה לבין החדשה!","\u0003אלא\u0004 תאמר שטעם האיסור הוא כדי ש\u0003לא ליהוי פסידא לתגרא\u0004 \u0005[יהא הפסד לתגר,\u0006 לסוחר\u0005]\u0006 שפעמים לא ישים לב להגדלת המידות וימכור לפי המחיר הישן.","אלא שהואיל ודרכו להרוויח שישית, הרי אם אין מוסיפים על המידות יותר משישית, נמצא שההפסד במידה ושיעור הרווח מתאזנים, ואינו מפסיד — אף על טעם זה יש לתמוה: \u0003פסידא\u0004 \u0005[הפסד]\u0006 \u0003הוא\u0004 ש\u0003לא ליהוי ליה\u0004 \u0005[יהא לו],\u0006 אבל \u0003רווחא לא בעי\u0004 \u0005[רווח אינו צריך]?\u0006 וכי נאמר לו, כפתגם העממי: \u0003\"זבן וזבין תגרא איקרי\"\u0004 \u0005[\"מכור וקנה\u0006 ו\u0005תגר היקרא\"]?\u0006 שאדם אינו מוכר וקונה ואינו מרוויח כלום רק על מנת להיקרא \"סוחר\", ובוודאי אי אפשר להניח לאדם לשהות בלא להרוויח דבר. ואם תקנה זו לצורך המוכר היא, בוודאי היו חכמים דואגים שירויח דבר מה!","\u0003אלא אמר רב חסדא:\u0004 טעמו של איסור זה, להוסיף שישית על המידות, אינו בגלל סברה, אלא \u0003שמואל קרא אשכח\u0004 \u0005[פסוק מצא]\u0006 \u0003ודרש,\u0004 שציוה יחזקאל על ערך ומשקל המטבעות השונים שישתמשו בהם: \u0003\"והשקל עשרים גרה, עשרים שקלים חמשה ועשרים שקלים עשרה וחמשה שקל המנה יהיה לכם\"\u0004 (יחזקאל מה, יב), ואם מצרפים את המספרים הללו יחד (עשרים, עשרים וחמישה, עשרה וחמישה) הרי אלו שישים שקלים, שעולים לפי הפסוק לשיעור של מנה."],["ויש לתהות: וכי שישים שקלים \u0003מנה\u0004 הם? והרי \u0003מאתן וארבעין הוו\u0004 \u0005[מאתים וארבעים\u0006 דינרים \u0005הם]!\u0006 שבכל שקל של מקרא (הקרוי במשנה \"סלע\") יש ארבעה דינרים, ואם כן נמצא שבמנה בן שישים שקלים (סלעים) יש מאתים וארבעים דינרים, ואילו אנו יודעים שבמנה יש עשרים וחמישה שקלים, דהיינו מאה דינרים! \u0003אלא שמע מינה תלת\u0004 \u0005[למד מכאן שלושה\u0006 דברים\u0005];\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מנה של קדש\u0004 שאליו התייחס יחזקאל, \u0003כפול היה\u0004 ואף מתחילה לא היה של עשרים וחמישה שקלים אלא של חמישים שקלים (כלומר, מאתים דינרים), \u0003ו\u0004ממה שיחזקאל אמר שהמנה יהא מעתה בן שישים שקלים, ולא בן חמישים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מוסיפין על המדות\u0004 (ובכלל זה המטבעות) \u0003ו\u0004אולם \u0003אין מוסיפין יותר משתות. ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003שתותא מלבר\u0004 \u0005[שישית\u0006 מחושבת \u0005מבחוץ],\u0006","כלומר, מן הסכום הסופי, הגדול יותר, שהוא חמישית מן הקטן. כגון כאן, שהוסיפו ארבעים על מאתיים, והם שישית ממאתיים וארבעים, וחמישית ממאתיים. מסופר: \u0003רב פפא בר שמואל תקין כיילא בר תלתא קפיזי\u0004 \u0005[התקין מידה\u0006 חדשה \u0005בת שלושה לוגים].\u0006 \u0003אמרו ליה\u0004 \u0005[לו],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל: אין מוסיפין על המדות יותר משתות\u0004 ואתה מוסיף שליש על המידה הקיימת של חצי קב (שהיא שני לוגים)! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא כיילא חדתא תקיני\u0004 \u0005[אני מידה חדשה תיקנתי].\u0006 \u0003שדריה\u0004 \u0005[שלחה],\u0006 את המידה הזו, \u0003לפומבדיתא ולא קבלוה, שדריה\u0004 \u0005[שלחה]\u0006 \u0003ל\u0004עיר \u0003פאפוניא וקבלוה, וקרו ליה\u0004 \u0005[וקראו לה]\u0006 \u0003רוז\u0004 (המידה של) \u0003פפא.\u0004","\u0003(סימן\u0004 להלכות הבאות: \u0003אוצרי פירות אין אוצרין ואין מוציאין ואין משתכרין פעמים בביצים מתריעין ולא מוציאין).\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אוצרי פירות\u0004 הצוברים פירות רבים ונמנעים למוכרם, ושומרים אותם ברשותם על מנת שיוכלו למוכרם ביוקר לאחר זמן עקב המחסור בהם ולהגדיל רווחיהם, \u0003ומלוי ברבית, ומקטיני איפה,\u0004 שמוכרים במידות קטנות מן השיעור הנכון, \u0003ומפקיעי שערים,\u0004 שמוכרים ביותר מן השער הנהוג באותו מקום — \u0003עליהן הכתוב אומר: \"לאמר מתי יעבר החדש ונשבירה שבר והשבת ונפתחה בר, להקטין איפה ולהגדיל שקל ולעות מאזני מרמה\"\u0004 (עמוס ח, ה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"נשבע ה' בגאון יעקב אם אשכח לנצח כל מעשיהם\"\u0004 (עמוס ח, ז).","\u0003אוצרי פירות\u0004 — \u0003כגון מאן\u0004 \u0005[מי]?\u0006 \u0003אמר ר' יוחנן: כגון שבתי אצר פירות,\u0004 שהיה קונה ואוגר פירות רבים ואחר כך היה מוכרם ביוקר.","\u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל מזבין להו לפירי בתרעא חרפא כתרעא חרפא\u0004 \u0005[היה מוכר פירות בשער החריף,\u0006 בזמן שהפירות בזול, \u0005כשער החריף,\u0006 כמחיר הזול\u0005].\u0006 \u0003שמואל בריה\u0004 \u0005[בנו]\u0006 שינה ממנהג אביו, והוא היה \u0003משהי לפירי\u0004 \u0005[משהה את הפירות\u0006 אצלו\u0005]\u0006 \u0003ומזבין להו בתרעא אפלא כתרעא חרפא\u0004 \u0005[ומוכר אותם בשער האפיל,\u0006 בזמן מאוחר יותר, כאשר המחירים גבוהים יותר, \u0005כ\u0006מחיר \u0005השער החריף,\u0006 הזול\u0005].\u0006 \u0003שלחו מתם\u0004 \u0005[משם]\u0006 מארץ ישראל: \u0003טבא דאבא מדברא\u0004 \u0005[טוב\u0006 מעשהו \u0005של האב משל בנו].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003תרעא\u0004 \u0005[השער]\u0006 ש\u0003רווח\u0004 — \u0003רווח,\u0004 שאם יש פירות בשוק והשער זול בתחילה, שוב לא יעלה המחיר הרבה במשך השנה, ונמצא זה שמוכר פירות בשעת השער החריף, כאביו של שמואל, מסייע לאנשים לאורך כל השנה. אך אם השער גבוה מתחילה שוב לא ניתן להוריד אותו בקלות.","\u0003אמר רב: עושה אדם את קבו אוצר,\u0004 שרשאי אדם להשהות לזמן מאוחר יותר את מכירת הקב שלו, כלומר, את יבול שדותיו שלו, ואינו חושש משום איסור אצירת פירות. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין אוצרין פירות דברים שיש בהן חיי נפש, כגון: יינות, שמנין וסלתות, אבל תבלין, כמון ופלפלין\u0004 — \u0003מותר. במה דברים אמורים\u0004 — \u0003בלוקח\u0004 (קונה) \u0003מן השוק, אבל במכניס משלו,\u0004 ממה שגידל שדהו — \u0003מותר.\u0004","\u0003ומותר לאדם לאצור פירות בארץ ישראל\u0004 \u0003שלש שנים,\u0004 שהן: \u0003ערב שביעית, ושביעית, ומוצאי שביעית,\u0004 מפני שאין עבודת אדמה בשביעית, ויש לחשוש שיעלו המחירים הרבה, ויהא מחסור ממשי באוכל.","\u0003ובשני בצורת\u0004 — \u0003אפילו קב חרובין לא יאצור, מפני שמכניס מארה\u0004 (קללה) \u0003בשערים,\u0004 שהכל חוששים ומפחדים מן המחסור, וכל תנודה בשוק יכולה לגרום לעליית שערים גדולה. וכן הלכה למעשה, וכפי ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי בר' חנינא\u0004 (שהיה בארץ ישראל) \u0003לפוגא שמעיה\u0004 \u0005[שמשו]:\u0006 \u0003פוק אצר\u0004 \u0005[צא, אסוף]\u0006 \u0003לי פירי\u0004 \u0005[פירות]\u0006 עבור שימושי במשך \u0003שלש שנים: ערב שביעית, ושביעית, ומוצאי שביעית.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מוציאין פירות מארץ ישראל דברים שיש בהן חיי נפש, כגון: יינות, שמנים וסלתות\u0004 מפני שגורם להתייקרות בארץ. \u0003ר' יהודה בן בתירא מתיר ביין, מפני שממעט\u0004 על ידי כך \u0003את התיפלה\u0004 (זנות). \u0003וכשם שאין מוציאין\u0004 פירות \u0003מארץ לחוץ לארץ, כך אין מוציאין מארץ ישראל לסוריא\u0004 שהיא נחשבת לענין זה כחוץ לארץ. \u0003ורבי מתיר\u0004"],["\u0003מהיפרכיא להיפרכיא\u0004 \u0005[ממחוז למחוז],\u0006 מהמחוז הצפוני ביותר של ארץ ישראל למחוז הדרומי ביותר של סוריה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין משתכרים,\u0004 כלומר, אין לעשות מסחר \u0003בארץ ישראל בדברים שיש בהן חיי נפש, כגון: יינות, שמנים וסלתות,\u0004 על מנת שלא לייקר את מחיריהם. אלא ימכרו המגדלים עצמם את תוצרתם בשוק.","\u0003אמרו עליו על ר' אלעזר בן עזריה, שהיה משתכר,\u0004 עושה מסחר, קונה מהיצרן ומוכר לאחרים בריווח, \u0003ביין ושמן.\u0004 ומסבירים: \u0003ביין\u0004 — \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה\u0004 בן בתירא שהתיר להוציא יין מארץ ישראל, משום שהוא גורם לחטא, ולדעתו אין צורך למנוע התייקרות של היין, \u0003בשמן\u0004 הטעם אחר, משום ש\u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003ר' אלעזר בן עזריה שכיח מישחא\u0004 \u0005[מצוי שמן],\u0006 ולכן גם כשנעשה בו מסחר, אין לחשוש שבכך יעלה מחירו ויקשה על חיי העניים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין משתכרין פעמים בביצים. אמר מרי בר מרי: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בפירוש אימרה זו \u0003רב ושמואל, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכוונה היא \u0003על חד תרי\u0004 \u0005[אחד שניים],\u0006 כלומר, אסור לסוחר להרוויח בהם פי שנים מהמחיר ששילם הוא עבורן. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אסור למכור מ\u0003תגר לתגרא\u0004 \u0005[מסוחר לסוחר],\u0006 אלא הסוחר שקנה מבעל הביצים הוא שימכור לצרכנים. ובהמשך למה שאמרו, שהטילו הגבלות בענין דברים שיש בהם חיי נפש, מביאים ברייתא שיש בה להדגיש ענין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מתריעין,\u0004 נאספים וצועקים בתפילה ברבים \u0003על פרקמטיא\u0004 (מסחר, סחורה) שהוזל מחירה, \u0003ואפילו בשבת\u0004 מותר לצעוק ולהתחנן, למרות שאין אדם רשאי לבקש על צרכיו בשבת, משום שהיא צרת רבים.","\u0003אמר ר' יוחנן:\u0004 הכוונה היא דווקא לסחורות שהן עיקרה של הכלכלה המקומית, \u0003כגון כלי\u0004 (בגדי) \u0003פשתן בבבל, ויין ושמן בארץ ישראל. אמר רב יוסף: והוא, דזל וקם\u0004 \u0005[שהוזל\u0006 מחיר הסחורה \u0005ועמד]\u0006 על שער כזה, שמה שהיה שווה מקודם \u0003עשרה\u0004 נמכר עכשיו \u0003בשיתא\u0004 \u0005[בשישה],\u0006 שדווקא על הוזלה כזו יש להתריע בתפילה ואף בשבת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין יוצאין מארץ\u0004 ישראל \u0003לחוץ לארץ,\u0004 שכן בצאתו לחוץ לארץ הריהו מפקיע את עצמו מן המצוות התלויות בה, \u0003אלא אם כן עמדו\u0004 (היה מחירם) של \u0003סאתים\u0004 תבואה \u0003בסלע\u0004 שהוא כפליים מן המחיר הרגיל, \u0003אמר ר' שמעון: אימתי\u0004 אמרו דבר זה? — \u0003בזמן שאינו מוצא ליקח\u0004 (לקנות) שאין לו כסף, \u0003אבל בזמן שמוצא ליקח, אפילו עמדה סאה בסלע\u0004 — \u0003לא יצא.\u0004","\u0003וכן היה ר' שמעון בן יוחאי אומר: אלימלך,\u0004 ו\u0003מחלון וכליון\u0004 בניו, \u0003גדולי הדור היו ופרנסי הדור היו, ומפני מה נענשו\u0004 שמתו בגולה? — \u0003מפני שיצאו מ\u0004ה\u0003ארץ לחוצה לארץ,\u0004 \u0003שנאמר: \"ותהם כל העיר עליהן ותאמרנה הזאת נעמי\"\u0004 (רות א, יט). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הזאת נעמי\"?\u0004 כיצד נלמד הדבר מכאן? \u0003אמר ר' יצחק, אמרו: חזיתם\u0004 \u0005[ראיתם]\u0006 \u0003נעמי שיצאת מארץ לחוץ לארץ מה עלתה לה?\u0004 מה אירע בגורלה? שלא זאת בלבד שלא ניצלה שם מצרות, אלא ירדה לגמרי ממעמדה.","\u0003ו\u0004עוד \u0003אמר ר' יצחק\u0004 בענין זה שבמגילת רות: \u0003אותו היום שבאת\u0004 (באה) \u0003רות המואביה לארץ ישראל, מתה אשתו של בעז,\u0004 שכבר אז נוצרה האפשרות — שהתממשה לאחר מכן — שתינשא רות לבועז. \u0003והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 בפתגם מקובל: \u0003עד\u0004 ש\u0003לא\u0004 (טרם) \u0003שכיב שיכבא\u0004 \u0005[מת המת]\u0006 — כבר \u0003קיימא מנו בייתיה\u0004 \u0005[עומד הממונה על ביתו],\u0006 ואף כאן האשה החדשה (רות) כבר באה למקומו של בועז עוד לפני שמתה אשתו.","ועוד בענין זה \u0003אמר רבה בר רב הונא אמר רב: אבצן\u0004 מבית לחם, הנמנה בין השופטים (ראה שופטים יב, ח–י), \u0003זה בעז.\u0004 ומסבירים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 ומה למדנו מכך? \u0003כי אידך\u0004 \u0005[כמו\u0006 האימרה \u0005האחרת]\u0006 של \u0003רבה בר רב הונא,\u0004 ש\u0003אמר רבה בר רב הונא אמר רב: מאה ועשרים משתאות עשה בעז לבניו\u0004 בחתונותיהם, \u0003שנאמר: \"ויהי לו שלשים בנים, ושלשים בנות שלח החוצה ושלשים בנות הביא לבניו מן החוץ, וישפט את ישראל שבע שנים\"\u0004 (שופטים יב ט), ששישים ילדים היו לו,","\u0003ובכל אחת ואחת\u0004 מן החתונות שעשה להם, \u0003עשה שני משתאות: אחד בבית אביו\u0004 של החתן \u0003ואחד בבית חמיו\u0004 אבי אשתו, \u0003ובכולן לא זימן את מנוח\u0004 אביו של שמשון, שאשתו היתה עקרה מתחילה (ראה שופטים יג, ב), \u0003אמר: כודנא\u0004 \u0005[פירדה]\u0006 \u0003עקרה במאי פרעא\u0004 \u0005[במה תפרע]\u0006 \u0003לי?\u0004 שהרי למנוח אבי שמשון לא היו ילדים, ולא כדאי לי להזמין אותו, שהרי הוא לא יזמינני אליו.","\u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וכולן\u0004 כל הילדים של אבצן \u0003מתו בחייו. והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 בפתגמם: \u0003\"בחייך\u0004 ש\u0003ילדת שיתין שיתין\u0004 \u0005[שישים, שישים\u0006 ילדים\u0005]\u0006 \u0003למה ליך\u0004 \u0005[לך]?\u0006 \u0003איכפל ואוליד חד דמשיתין זריז\u0004 \u0005[השתדל והולד אחד, שיהיה זריז משישים]\u0006","\u0003\",\u0004 כבועז, שמתו ששים ילדיו, וילדו האחרון שהוליד מרות, הוא כבודו, שממנו באה מלכות בית דוד. \u0003(סימן\u0004 לדברים שאמר רב חנן בר רבא בשם רב: \u0003מלך אברהם עשר שנים שנפטר נתנשא לבדו). אמר רב חנן בר רבא אמר רב: אלימלך, ושלמון\u0004 (אביו של בועז), \u0003ופלוני אלמוני\u0004 הנזכר (בעילום שמו) בספר רות (\"ויאמר סורה שבה פה פלוני אלמוני ויסר וישב\". רות ד, א) כגואל קרוב יותר מבועז, \u0003ואבי נעמי\u0004 — \u0003כולן בני\u0004 (צאצאי) \u0003נחשון בן עמינדב\u0004 נשיא שבט יהודה \u0003הן\u0004 (ראה רות ד, כ–כא). ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 — \u0003שאפילו מי שיש לו זכות אבות\u0004 כאלימלך, \u0003אינה עומדת לו בשעה שיוצא מ\u0004ה\u0003ארץ לחוצה לארץ.\u0004 אגב הזכרת דברי רב חנן בר רבא מביאים עוד מדבריו.","\u0003ואמר רב חנן בר רבא אמר רב: אמיה\u0004 \u0005[אמו]\u0006 של \u0003אברהם\u0004 — \u0003אמתלאי בת כרנבו\u0004 היה שמה, \u0003אמיה\u0004 \u0005[אמו]\u0006 של \u0003המן\u0004 — \u0003אמתלאי בת עורבתי\u0004 שמה, \u0003וסימניך\u0004 כדי שלא תבלבל ביניהן: \u0003טמא\u0004 — \u0003טמא,\u0004 כלומר, עורב שהוא טמא, סימן לזיכרון שם אמו של המן שהוא טמא, \u0003טהור\u0004 שהוא כבש (\"כר\") — סימן ל\u0003טהור,\u0004 לאמו של אברהם שהוא טהור.","\u0003אמיה\u0004 \u0005[אמו]\u0006 של \u0003דוד\u0004 — \u0003נצבת בת עדאל שמה, אמיה\u0004 \u0005[אמו]\u0006 של \u0003שמשון\u0004 — \u0003צללפונית, ואחתיה\u0004 \u0005[ואחותו]\u0006 היתה נקראת \u0003נשיין.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה אנו למדים מידיעתם של כל השמות הללו? ומשיבים: \u0003לתשובת המינים\u0004 ששואלים על שמותיהן של הנשים הללו, שאינם מפורשים במקרא, ואנו אומרים לנו שמסורת בידינו בעל פה מה שמותיהן.","\u0003ואמר רב חנן בר רבא אמר רב: עשר שנים נחבש אברהם אבינו\u0004 בכלא, על שכפר בעבודה זרה שהיתה נהוגה בארצו, והן נחלקות באופן זה: \u0003שלש\u0004 שנים \u0003ב\u0004עיר \u0003כותא, ושבע ב\u0004עיר \u0003קרדו. ורב דימי מנהרדעא מתני איפכא\u0004 \u0005[היה שונה להיפך],\u0006 שבע בכותא ושלוש בקרדו. \u0003אמר רב חסדא: עיברא זעירא\u0004 \u0005[המעבר הקטן]\u0006 של \u0003כותא זהו אור כשדים.\u0004","\u0003ואמר רב חנן בר רבא אמר רב: אותו היום שנפטר אברהם אבינו מן העולם, עמדו כל גדולי אומות העולם בשורה\u0004 כדרך שעושים אבלים, \u0003ואמרו: אוי לו לעולם שאבד\u0004"],["\u0003מנהיגו, ואוי לה לספינה שאבד קברינטא\u0004 (רב החובל שלה). ועוד בענין מנהיגים.","נאמר בשבחיו של מקום: על מה שנאמר \u0003\"והמתנשא לכל לראש\"\u0004 (דברי הימים א כט, יא) \u0003אמר רב חנן בר רבא אמר רב: אפילו ריש גרגותא\u0004 (הממונה על חלוקת המים להשקייה) \u0003משמיא מוקמי ליה\u0004 \u0005[משמים מעמידים אותו],\u0006 שכל מי שנעשה ראש, אפילו בדבר קטן — משמים הוא מתמנה. ושבים לדון בעניינם של אלימלך ובניו, שלדעת ר' שמעון בר יוחי נענשו על שיצאו מן הארץ שלא כדין.","\u0003אמר רב חייא בר אבין אמר ר' יהושע בן קרחה: חס ושלום\u0004 שזה היה חטאם, \u0003ש\u0004כן \u0003אפילו\u0004 אם \u0003מצאו\u0004 אלימלך ובניו \u0003סובין\u0004 לאכול \u0003לא יצאו\u0004 מן הארץ, \u0003ואלא מפני מה נענשו?\u0004 מטעם אחר — \u0003שהיה להן לבקש רחמים על דורם ולא בקשו, שנאמר: \"בזעקך יצילך קבוציך\"\u0004 (ישעיה נז, יג).","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שאסור לצאת מן הארץ \u0003אלא\u0004 בזמן ש\u0003מעות בזול,\u0004 כאשר הכסף מצוי, \u0003ופירות ביוקר\u0004 וכמו ששנינו: סאתים בסלע. \u0003אבל\u0004 בזמן ש\u0003מעות ביוקר\u0004 ואין אנשים יכולים להרוויח די כסף כדי לקנות אוכל \u0003אפילו עמדו ארבע סאין בסלע\u0004 — \u0003יוצאין\u0004 לחוץ לארץ על מנת לחיות.","\u0003(סימן\u0004 לרשימה של דברים שאמר ר' יוחנן שהוא זוכר מן העבר: \u0003סלע פועל חרובא טליא אמרין).\u0004 שכך \u0003אמר ר' יוחנן: נהירנא כד הוו קיימין ארבע סאין\u0004 \u0005[זוכר אני\u0006 כאשר \u0005היו עומדים,\u0006 נמכרים \u0005ארבעה סאים]\u0006 \u0003בסלע, והוו נפישי נפיחי כפן בטבריא מדלית\u0004 \u0005[והיו מרובים נפוחי רעב בטבריה מפני שלא]\u0006 היה להם אפילו מטבע קטנה כ\u0003איסר\u0004 לקנות בה. \u0003ו\u0004עוד \u0003אמר ר' יוחנן: נהירנא כד\u0004 \u0005[זוכר אני כאשר]\u0006 \u0003לא הוו מיתגרין פועליא למדנח קרתא\u0004 \u0005[היו נשכרים פועלים למזרח העיר],\u0006 \u0003מריח פיתא\u0004 \u0005[הפת]\u0006 שהיה בא ממערב \u0003מייתין\u0004 \u0005[היו מתים].\u0006","ואגב כך מספרים עוד דברי זכרונות, \u0003ואמר ר' יוחנן: נהירנא כד הוה בצע ינוקא חרובא, והוה נגיד חוטא דדובשא על תרין דרעוהי\u0004 \u0005[זוכר אני כאשר היה שובר ילד חרוב, והיה נמשך חוט דבש על שתי זרועותיו].\u0006 \u0003ואמר ר' אלעזר: נהירנא כד הוה נטיל עורבא בשרא, ונגיד חוטא דמשחא מריש שורא ועד לארעא\u0004 \u0005[זוכר אני כאשר היה עורב לוקח בשר, והיה נמשך חוט של שומן מראש החומה\u0006 שעמד עליה \u0005ועד לארץ].\u0006 \u0003ואמר ר' יוחנן: נהירנא כד הוו מטיילין טליא וטלייתא בשוקא כבר שית\u0004 \u0005[זוכר אני כאשר היו מטיילים נער ונערה בשוק, כבן שש]\u0006 \u0003עשרה וכבר\u0004 \u0005[וכבן]\u0006 \u0003שבע עשרה, ולא הוו חטאן\u0004 \u0005[היו חוטאים].\u0006 \u0003ואמר ר' יוחנן: נהירנא כד הוו אמרין בי מדרשא\u0004 \u0005[זוכר אני כאשר היו אומרים\u0006 ב\u0005בית המדרש]:\u0006 \u0003דמודי להון\u0004 \u0005[\u0006מי \u0005שמודה להם\u0006 לגויים\u0005]\u0006 — \u0003נפיל בידיהון\u0004 \u0005[נופל בידיהם].\u0006 \u0003דמתרחיץ עליהון\u0004 \u0005[\u0006זה \u0005שסומך עליהם]\u0006 — \u0003דיליה דילהון\u0004 \u0005[שלו\u0006 נעשה \u0005שלהם].\u0006 ושבים לדון בעניינים שבמגילת רות.","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מחלון וכליון\"\u0004 (רות א, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"\u0004ו\u0003יואש ושרף\u0004 אשר בעלו למואב\u0003\"\u0004 (דברי הימים א ד, כב), ומשמע שהם אותם אנשים שנשאו נשים ממואב. \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"מחלון\" ו\"כליון\" שמן\u0004 האמיתי, \u0003ולמה נקרא שמן \"שרף\" ו\"יואש\"? \"יואש\"\u0004 נקרא כך משום \u0003שנתיאשו מן הגאולה\u0004 בארץ, שהרי קבעו דירתם במואב וישבו שם שנים רבות. \u0003\"שרף\"\u0004 נקרא כך מפני \u0003שנתחייבו שריפה למקום\u0004 משום שעזבו את הארץ.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"יואש\" ו\"שרף\" שמן\u0004 האמיתי, \u0003ולמה נקרא שמן \"מחלון\" ו\"כליון\"? \"מחלון\"\u0004 — \u0003שעשו גופן\u0004 (עצמם) \u0003חולין\u0004 שהרי יצאו לחוץ לארץ שהיא טמאה, \u0003ו\"כליון\"\u0004 — \u0003שנתחייבו כליה למקום.\u0004","ומעירים: \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמי שאומר]:\u0006 \u0003\"מחלון\" ו\"כליון\" שמן; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויוקים ואנשי כזבא ויואש ושרף אשר בעלו למואב וישבי לחם והדברים עתיקים\"\u0004 (דברי הימים א ד, כב)? ומסבירים: \u0003\"ויוקים\"\u0004 — \u0003זה יהושע, שהקים\u0004 ושמר את ה\u0003שבועה לאנשי גבעון\u0004 (ראה יהושע פרק ט), \u0003\"ואנשי כזבא\"\u0004 — \u0003אלו אנשי גבעון,\u0004 \u0003שכזבו ביהושע,\u0004 שהרי רימוהו באומרם שהם מארץ רחוקה. \u0003\"ויואש ושרף\"\u0004 — \u0003אלו מחלון וכליון, ולמה נקרא שמן \"יואש\" ו\"שרף\"? \"יואש\"\u0004 — על שם \u0003שנתיאשו מן הגאולה, \"שרף\"\u0004 — משום \u0003שנתחייבו שריפה למקום.\u0004 \u0003\"אשר בעלו למואב\"\u0004 — כוונתו \u0003שנשאו נשים מואביות. \"וישבי לחם\"\u0004 — \u0003זו רות המואביה, ששבה ונדבקה בבית לחם יהודה. \"והדברים עתיקים\"\u0004 — \u0003דברים הללו עתיק יומיא\u0004 \u0005[עתיק ימים,\u0006 הקדוש ברוך הוא\u0005]\u0006 \u0003אמרן,\u0004 שגזירה היתה מלפניו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מצאתי דוד עבדי\"\u0004 (תהלים פט, כא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לשון מציאה גם בבנות לוט: \u0003\"שתי בנתיך הנמצאת\"\u0004 (בראשית יט, טו), לומר שנמצא שורש דוד מראשית הדורות וכבר היה נועד דוד לצאת ממואב, בנם של לוט ובתו (ראה בראשית יט, לז). אגב הזכרת פסוק זה מביאים את מה שנאמר בהמשך: \u0003\"המה היוצרים וישבי נטעים וגדרה עם המלך במלאכתו ישבו שם\"\u0004 (דברי הימים א ד, כג), ומבארים: \u0003\"המה היוצרים\"\u0004 — \u0003אלו בני יונדב בן רכב שנצרו\u0004 (שמרו) את \u0003שבועת אביהם\u0004 (ראה ירמיהו ל״ה:ו׳). \u0003\"ישבי נטעים\"\u0004 — \u0003זה שלמה, ש\u0004היה \u0003דומה לנטיעה במלכותו. \"וגדרה\"\u0004 — \u0003זו סנהדרין שגדרו פרצותיהן של ישראל\u0004 על ידי לימודם ותקנותיהם. \u0003\"עם המלך במלאכתו ישבו שם\"\u0004 — \u0003זו רות המואביה שראתה במלכות שלמה\u0004 שהיה \u0003בן בנו של בן בנה, שנאמר\u0004 בשלמה: \u0003\"וישם כסא לאם המלך\"\u0004 (מלכים א ב, יט), \u0003ואמר ר' אלעזר:\u0004 הכוונה היא \u0003לאמה של\u0004 שושלת ה\u0003מלכות,\u0004 שהיא רות, שממנה צמחה השושלת כולה. ומתוך שעסקו בזמנים שיש בהם רעב בארץ, מסיימים את הפרק בברכה באותם עניינים עצמם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בפרשת הברכות \u0003\"ואכלתם מן התבואה ישן\"\u0004 (ויקרא כה, כב) הכוונה היא \u0003בלא סלמנטון.\u0004 ושואלים בגמרא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בלא סלמנטון\"? רב נחמן אמר: בלא רצינתא\u0004 \u0005[תולעים]\u0006 האוכלות את התבואה. \u0003ורב ששת אמר: בלא שדיפא\u0004 \u0005[שידפון]\u0006 המקלקל את טעמה של התבואה.","","","","","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ששת,\u0004 וכן \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן.\u0004 ומפרטים, \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן.\u0004 מה שנאמר \u0003\"ואכלתם\u0004 מן התבואה \u0003ישן\"\u0004 (ויקרא כה, כב), \u0003יכול\u0004 אולי מכלל הדברים משמע ש\u0003יהו ישראל מצפין לחדש מפני ישן שכלה?\u0004 — \u0003תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"עד בוא תבואתה\",\u0004 לומר: \u0003עד שתבא תבואה מאליה\u0004 ואין מצפים לה, שנתקיימה הברכה ואין התולעת אוכלת את החיטה מן האוצר. \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ששת: \"ואכלתם מן התבואה ישן\"\u0004 — \u0003יכול\u0004 אולי מכלל הדברים משמע ש\u0003יהו ישראל מצפין לחדש מפני ישן שרע\u0004 שאינו טוב, מפני השדפון שמקלקל את התבואה? — \u0003תלמוד לומר: \"עד בוא תבואתה\"\u0004 — \u0003עד שתבא תבואה מאליה,\u0004 שלא היה שדפון בתבואה שבאוצר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בפרשת הברכות \u0003\"ואכלתם ישן נושן\"\u0004 (ויקרא כו, י), \u0003מלמד שכל המיושן מחבירו הוי\u0004 \u0005[הריהו]\u0006 \u0003יפה מחבירו. ואין לי אלא דברים שדרכן ליישנן,\u0004 כלומר, שדרך העולם היא שמשאירים אותם להתיישן כגון יין, \u0003דברים שאין דרכן ליישנן\u0004 כגון פירות, \u0003מנין\u0004 שיהו טובים ככל שיתיישנו? — \u0003תלמוד לומר: \"ישן נושן\" מכל מקום,\u0004 שהארץ תשמור את פירותיה שלא יתקלקלו כלל ואף יוסיפו וישתבחו.","","","ומה שנאמר \u0003\"וישן מפני חדש תוציאו\"\u0004 (ויקרא כו, י) \u0003מלמד שהיו אוצרות מלאין ישן וגרנות מלאין חדש, והיו ישראל אומרים: היאך נוציא זה מפני זה? אמר רב פפא: כל מילי עתיקא מעליא\u0004 \u0005[דבר ישן מעולה\u0006 בטיבו\u0005]\u0006 מן החדש, \u0003לבר מתמרי ושיכרא והרסנא\u0004",""],["\u0003המוכר פירות לחברו\u0004 כלומר, מכר לו זרעים (כגון חיטים ושעורים או פולים וכיוצא בהם) הנמכרים הן לאכילה והן לזריעה, \u0003וזרען\u0004 הקונה \u0003ולא צמחו, ואפילו\u0004 קנה ממנו \u0003זרע פשתן\u0004 שאינו נמכר כל כך לאכילה, ולא צמח — \u0003אינו חייב\u0004 המוכר \u0003באחריותן\u0004 מכיון שלא אמר לו הקונה שהוא מתכוון לזריעה, ויכול המוכר לומר שסבר שקנה אותם לאכילה. \u0003רבן שמעון בן גמליאל אומר: זרעוני גינה שאינן נאכלין\u0004 כלל, וזרעם הקונה ולא צמחו — \u0003חייב\u0004 המוכר \u0003באחריותן\u0004 שמובן שקנה אותם לזריעה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המוכר שור לחבירו, ונמצא\u0004 השור \u0003נגחן\u0004 ואינו יכול לעבוד בו, \u0003רב אמר: הרי זה מקח טעות, ושמואל אמר: יכול\u0004 המוכר \u0003לומר לו: לשחיטה מכרתיו לך.\u0004","ושואלים על כך: \u0003וליחזי\u0004 \u0005[ונראה]\u0006 מה טיבו של הקונה, \u0003אי גברא\u0004 \u0003דזבין לנכסתא\u0004 \u0005[אם\u0006 הוא \u0005אדם שקונה לשחיטה]\u0006 כגון שהיה הקונה מוכר בשר — ודאי קנה \u0003לנכסתא\u0004 \u0005[לשחיטה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא אדם שקונה \u0003לרדיא\u0004 \u0005[לחרישה]\u0006 כגון חקלאי העובד בשדה — ודאי קנה אותו \u0003לרדיא\u0004 \u0005[לחרישה]\u0006 לעבוד בו! ומשיבים: מדובר \u0003בגברא דזבין להכי ולהכי\u0004 \u0005[באדם שקונה לכך ולכך].\u0006","ושואלים: \u0003וליחזי דמי היכי נינהו\u0004 \u0005[ונראה\u0006 את \u0005המחיר\u0006 ששילם הקונה \u0005איך הוא],\u0006 שמחיר שור לחרישה גדול יותר!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 \u0003דאייקר בישרא וקם בדמי רדיא\u0004 \u0005[שהתייקר הבשר ועמד בדמי\u0006 שור ל\u0005חרישה].\u0006 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהמחירים שווים, \u0003למאי נפקא מינה\u0004 \u0005[מה,\u0006 איזה הבדל, \u0005יוצא מזה]?\u0006 מה זה משנה לקונה, והרי אין הוא מפסיד דבר! ומשיבים: \u0003נפקא מינה לטרחא\u0004 \u0005[יוצא מכאן\u0006 הבדל \u0005לטרחה]\u0006 שצריך לטרוח למכור לשחיטה את השור שקנה, ולקנות שור חדש. ויש בזה משום מיקח טעות לדעת רב, ולפיכך, לדעתו, רשאי הקונה להחזיר את השור ולדרוש את דמיו.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006"],["\u0003אי דליכא לאישתלומי מיניה\u0004 \u0005[אם אין\u0006 אפשרות לקונה \u0005לקבל\u0006 \u0005תשלום ממנו,\u0006 מן המוכר\u0005]\u0006 שהוציא כבר את הכסף שקיבל עבור שורו — \u0003ליעכב תורא בזוזיה\u0004 \u0005[שיעכב\u0006 את \u0005השור בכספו]\u0006 ויהא שור זה כתשלום לממון שמגיע לו, \u0003דאמרי אינשי\u0004 \u0005[ש\u0006הרי כך \u0005אומרים אנשים]\u0006 בפתגם מקובל: \u0003מן מרי רשותיך פארי אפרע\u0004 \u0005[מהחייב לך\u0006 אפילו \u0005תבן היפרע],\u0006 שאם אינו יכול לקבל כסף —","שיקבל כל דבר אחר השווה כסף! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה \u0003דאיכא לאישתלומי מיניה\u0004 \u0005[שיש\u0006 אפשרות \u0005לקבל תשלום ממנו]\u0006 בממון, ובכך נחלקו,","\u0003רב אמר: הרי זה מקח טעות,\u0004 שהרי \u0003בתר רובא אזלינן\u0004 \u0005[אחר הרוב אנו הולכים],\u0006 \u0003ורובא לרדיא זבני\u0004 \u0005[והרוב קונים\u0006 שוורים \u0005לחרישה],\u0006 ולכן צריך המוכר להחזיר לו את כספו. \u0003ושמואל אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך: כי אזלינן בתר רובא\u0004 \u0005[כאשר אנו הולכים אחר הרוב]\u0006 — הרי זה \u0003באיסורא\u0004 \u0005[ב\u0006עניינים של \u0005איסור\u0006 והיתר\u0005],\u0006 \u0003בממונא\u0004 \u0005[ב\u0006ענייני \u0005ממונות]\u0006 — \u0003לא\u0004 הולכים אחר הרוב, אלא הכלל הקובע הוא: המוציא מחבירו עליו הראיה.","\u0003(סימן\u0004 לראיות שמביאים בבירור המחלוקת הזו: \u0003אשה ועבד שור שורין ופירות).\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003האשה שנתאלמנה או נתגרשה, והיא אומרת:\u0004 \u0003ב\u0004\u0003תולה נישאתי\u0004 ולכן מגיעה לי כתובה של מאתיים זוז, \u0003והוא\u0004 (או יורשיו) \u0003אומר: לא כי, אלא אלמנה נשאתיך\u0004 ומגיע לך רק מאה זוז, הרי \u0003אם יש עדים ש\u0004בחופתה \u0003יצאה בהינומא וראשה פרוע\u0004 והרי זה כדרך הבתולות הנישאות — \u0003כתובתה מאתים.\u0004","ונדייק מכאן: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא \u0005שיש]\u0006 \u0003עדים\u0004 על כך, \u0003הא ליכא\u0004 \u0005[אבל\u0006 אם \u0005אין]\u0006 \u0003עדים\u0004 — \u0003לא, ואמאי\u0004 \u0005[ומדוע]?\u0006 לשיטת רב \u0003לימא\u0004 \u0005[אמור]:\u0006 \u0003הלך אחר רוב הנשים, ורוב נשים\u0004 כשהן \u0003בתולות\u0004 הן \u0003נישאות!\u0004","\u0003אמר רבינא, משום דאיכא למימר\u0004 \u0005[שיש לומר]\u0006 כנגד זה: אמנם \u0003רוב נשים בתולות נישאות, ו\u0004אולם יש \u0003מיעוט\u0004 — הנישאות \u0003אלמנות. ו\u0004עוד, \u0003כל הנישאת בתולה יש לה קול\u0004 (פרסום) שכך נישאה, \u0003וזו\u0004 המתדיינת \u0003הואיל ואין לה קול\u0004 ואין יודעים אם נישאת בתולה — \u0003איתרע\u0004 \u0005[הורע]\u0006 \u0003לה רובא\u0004 \u0005[הרוב]\u0006 שרוב הנשים נישאות בתולות, וכיון שכן יש צורך בעדים כדי להוציא ממון מן הבעל.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר ש\u0003כל הנישאות בתולות יש להן קול,\u0004 אם כן, גם \u0003כי איכא\u0004 \u0005[כאשר יש]\u0006 \u0003עדים מאי הוי\u0004 \u0005[מה בכך]?\u0006 והרי \u0003מדלית\u0004 \u0005[מכיון שאין]\u0006 \u0003לה קול\u0004 — \u0003סהדי שקרי נינהו\u0004 \u0005[עדי שקר הם]!\u0006","\u0003אלא,\u0004 כך צריך לומר: \u0003רוב הנישאות\u0004 כשהן \u0003בתולות יש להן קול, וזו הואיל ואין לה קול\u0004 — \u0003איתרע\u0004 \u0005[הורע]\u0006 \u0003לה רובא\u0004 \u0005[הרוב],\u0006 אבל בדרך כלל הולכים אף בממון אחר הרוב.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו בברייתא: \u0003המוכר עבד לחברו ונמצא\u0004 העבד \u0003גנב או קוביוסטוס\u0004 (שטוף במשחק בקוביה), והרי זה אינו עבד ראוי — \u0003הגיעו,\u0004 כלומר, המיקח נגמר, ואין הקונה יכול לטעון שהיה זה מיקח טעות. אם היה העבד \u0003לסטים מזויין\u0004 (שודד) \u0003או מוכתב למלכות\u0004 (שנידון ליהרג) — \u0003אומר לו\u0004 הקונה למוכר: \u0003הרי שלך לפניך\u0004 וקח אותו והשב לו את כספי.","ויש לשאול: \u0003רישא\u0004 \u0005[בתחילה,\u0006 במקרה הראשון\u0005]\u0006 שנמצא גנב או קוביוסטוס,"],["\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין זה מיקח טעות? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דרובא הכי איתנהו\u0004 \u0005[שרוב\u0006 העבדים \u0005כך הם]?\u0006 ונמצא שסומכים על הרוב אף בממונות, שלא כשמואל!","ודוחים: \u0003לא, כולהו הכי איתנהו\u0004 \u0005[כולם,\u0006 כל העבדים \u0005כך הם],\u0006","גנבים או משחקי קוביה, ולכן אין לקונה מקום לטענת מיקח טעות. ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003שור שנגח את הפרה\u0004 והמיתה \u0003ונמצא עוברה\u0004 מת \u0003בצדה, ואינו ידוע אם עד שלא נגחה ילדה\u0004 והעובר מת מעצמו ולא כתוצאה מהנגיחה, \u0003או אם משנגחה ילדה\u0004 והשור הוא שגרם לנזק זה — בעל השור \u0003משלם חצי נזק לפרה\u0004 כדינו של כל שור תם שנגח, \u0003ורביע\u0004 (רבע) נזק \u0003לולד\u0004 משום הספק אם השור הוא שגרם לנזק.","\u0003ו\u0004אולם לשיטת רב שהולכים בממון אחר הרוב \u0003אמאי\u0004 \u0005[מדוע\u0006 חוששים לספק זה\u0005]?\u0006 \u0003לימא\u0004 \u0005[אמור]:\u0006 \u0003לך אחר רוב פרות, ורוב פרות מתעברות ויולדות\u0004 וולד חי בזמן הראוי, \u0003והא\u0004 \u0005[וזו]\u0006 שלפנינו, שוולדה הוא וולד מת, \u0003ודאי מחמת נגיחה הפילה!\u0004","ומשיבים: אף אם הולכים בממון אחר הרוב, מכל מקום \u0003התם\u0004 \u0005[שם]\u0006 אין לחייב את בעל השור בכל התשלום בגלל רוב זה, \u0003משום דמספקא לן\u0004 \u0005[שמסופק לנו]\u0006 אם יש לחייבו, אפילו אם מחמת השור הפילה, \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]:\u0006 \u0003מקמה אתא ומביעתותא\u0004 \u0005[מלפניה בא\u0006 השור, \u0005ומפחדו]\u0006 נבהלה ו\u0003הפילה,\u0004 אבל לא מחמת נגיחה, ואין נזק זה נחשב שנעשה על ידי השור, \u0003ואיכא למימר\u0004 \u0005[ויש\u0006 מקום \u0005לומר]:\u0006 \u0003מאחורה אתא ומינגח נגחה\u0004 \u0005[מאחוריה בא ונגחה\u0006 ממש\u0005]\u0006 \u0003והפילה\u0004 בגלל הנגיחה, אם כן, \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ממון המוטל בספק, וכל ממון המוטל בספק חולקין.\u0004","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שרב ושמואל נחלקו במחלוקת שנחלקו בה כבר \u0005תנאים],\u0006 ששנינו בברייתא: \u0003שור שהיה רועה, ונמצא שור הרוג בצדו, אף על פי שזה\u0004 המת \u0003מנוגח וזה\u0004 השני, החי, \u0003מועד ליגח,\u0004 או \u0003זה מנושך וזה מועד לישוך\u0004 — \u0003אין אומרים: בידוע\u0004 (בוודאי) \u0003שזה נגחו וזה נשכו,\u0004 ואין מוציאים כסף מבעל השור המועד על סמך הנחה מעין זו. ואילו \u0003ר' אחא אומר\u0004 לגבי מקרה דומה: \u0003גמל האוחר\u0004 (גמל מיוחם המשתולל) \u0003בין הגמלים, ונמצא גמל הרוג בצדו\u0004 — \u0003בידוע שזה הרגו,\u0004 שחזקה היא שהוא שהרג.","ותחילה מסבירים: \u0003סברוה\u0004 \u0005[סברו\u0006 חכמים\u0005]\u0006 שמידת תוקף הראיה של \u0003רובא\u0004 \u0005[רוב]\u0006 \u0003וחזקה כי הדדי נינהו\u0004 \u0005[זה כמו זה הם]\u0006 ותוקפם שווה, ואם כן, \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003רב\u0004 ש\u0003אמר\u0004 שהולכים בממון אחר הרוב, סבור \u0003כר' אחא\u0004 שהולכים אחר החזקה. \u0003ושמואל\u0004 ש\u0003אמר\u0004 שאין הולכים בממון אחר הרוב, סבור \u0003כתנא קמא\u0004 \u0005[הראשון],\u0006 שאין הולכים אחר החזקה בממון!","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את שיטתי \u0003אפילו ל\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 אמרתי, וכיצד? \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 ה\u0003תנא קמא התם\u0004 \u0005[הראשון שם]\u0006 בענין שור שנמצא שור הרוג בצידו, \u0003אלא דלא אזלינן בתר\u0004 \u0005[שאין אנו הולכים\u0006 בממון \u0005אחר]\u0006 \u0003חזקה, אבל בתר רובא אזלינן\u0004 \u0005[אחר הרוב הולכים אנו].\u0006","\u0003ושמואל אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 לצד השני: \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי, \u0003אפילו ל\u0004שיטת \u0003ר' אחא\u0004 אמרתי, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אחא התם\u0004 \u0005[שם]\u0006 \u0003אלא דאזלינן בתר\u0004 \u0005[שהולכים\u0006 אנו בממון \u0005אחר]\u0006 \u0003חזקה,\u0004 משום ש\u0003הוא\u0004 הגמל \u0003גופיה\u0004 \u0005[עצמו]\u0006 הריהו \u0003מוחזק\u0004 כמסוכן, \u0003אבל בתר רובא לא אזלינן\u0004 \u0005[אחר רוב,\u0006 שאינו מצוי לפנינו, \u0005אין אנו הולכים].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לאחד מן הצדדים, ממה ששנינו במשנתנו: \u0003המוכר פירות לחברו וזרען ולא צמחו, ואפילו זרע פשתן\u0004 — \u0003אינו חייב באחריותן.\u0004","ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005],\u0006 למה הכוונה במה שאמרו \u0003\"אפילו\"? לאו\u0004 \u0005[\u0006האם \u0005אין]\u0006 הכוונה \u0003אפילו זרע פשתן, דרובא\u0004 \u0005[שהרוב]\u0006 \u0003לזריעה זבני\u0004 \u0005[קונים\u0006 אותו\u0005],\u0006 \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא אזלינן בתר רובא\u0004 \u0005[אין אנו הולכים אחר הרוב]?\u0006","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בנושא זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר פירות לחברו וזרען ולא צמחו,\u0004 אם היו אלה \u0003זרעוני גינה שאין נאכלין\u0004 — \u0003חייב באחריותן.\u0004 אם היה זה \u0003זרע פשתן\u0004 — \u0003אינו חייב באחריותן,\u0004 שהרי מקצתם נקנים לשם עשיית שמן או לצורך אחר. \u0003ר' יוסי אומר:\u0004"],["\u0003נותן לו דמי זרע,\u0004 שרוב זרעי הפשתן שימושם לזריעה. \u0003אמרו לו: הרבה לוקחין\u0004 (קונים) \u0003אותו לדברים אחרים\u0004 ולא לזריעה.","ושואלים: \u0003מאן תנאי\u0004 \u0005[מי\u0006 הם אותם \u0005התנאים]\u0006 שאמרנו שחולקים בשאלה האם הולכים אחר הרוב בממונות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003ר' יוסי ו\u0004אותם \u0003המצויינים כ\u0004\u0003\"אמרו לו\",\u0004 והרי \u0003תרוייהו בתר רובא אזלי\u0004 \u0005[שניהם אחר הרוב הולכים],\u0006 אלא שנחלקו אחר איזה רוב יש ללכת: \u0003מר אזיל בתר רובא דאינשי\u0004 \u0005[חכם\u0006 זה, \"אמרו לו\", \u0005הולך אחר רוב האנשים],\u0006 שמספר האנשים שקונים לדברים אחרים גדול מהקונים לזריעה, \u0003ומר אזיל בתר רובא\u0004 \u0005[וחכם\u0006 זה, ר' יוסי, \u0005הולך אחר רוב]\u0006 ה\u0003זריעה\u0004 שרוב הזרעים הנמכרים — נמכרים לזריעה!","\u0003אלא,\u0004 מחלוקת התנאים בענין רוב בממונות היא \u0003אי\u0004 \u0005[או]\u0006 מחלוקתם של \u0003ה\u0004\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ור' יוסי, אי\u0004 \u0005[או]\u0006 מחלוקתם של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ו\"אמרו לו\",\u0004 שהתנא הראשון סבור שאין הולכים בממון אחר הרוב.","על האמור שזרעוני גינה שלא צמחו חייב באחריותם \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מהו נותן לו\u0004 המוכר לקונה? — \u0003דמי זרע,\u0004 דמי הזרעים עצמם \u0003ו\u0004אולם \u0003לא הוצאה\u0004 שהוציא בזריעתם, כגון שכירת פועלים וכיוצא בזה. \u0003ויש אומרים\u0004 ש\u0003אף\u0004 את ה\u0003הוצאה\u0004 משלם לו.","ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003יש אומרים\u0004 אלה? \u0003אמר רב חסדא:\u0004 שיטת \u0003רבן שמעון בן גמליאל היא.\u0004","ושואלים: \u0003הי\u0004 \u0005[לאיזה]\u0006 דבר מדברי \u0003רבן שמעון בן גמליאל\u0004 מתכוון רב חסדא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003רבן שמעון בן גמליאל דמתניתין\u0004 \u0005[של משנתנו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוכר פירות לחבירו וזרען ולא צמחו, ואפילו זרע פשתן\u0004 — \u0003אינו חייב באחריותן,\u0004 ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם מכר \u0003זרעוני גינה שאינן נאכלין\u0004 כלל — \u0003חייב באחריותן.\u0004","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: זרעוני גינה שאינן נאכלין\u0004 — \u0003חייב באחריותן;\u0004 והרי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003נמי הכי קאמר\u0004 \u0005[גם כן כך אמר]\u0006 כפי שדייקנו: \u0003זרע פשתן הוא\u0004 ש\u0003אינו חייב באחריותן,\u0004 ומכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003זרעוני גינה שאינן נאכלין\u0004 — \u0003חייב באחריותן!\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר כי בענין \u0003הוצאה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 שנותן לו רק \u0003דמי זרע, ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 שנותן לו \u0003אף הוצאה,\u0004 ומכאן סבור רב חסדא שרבן שמעון בן גמליאל הוא \"יש אומרים\" שבברייתא.","על כך יש להקשות: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה יודע שרבן שמעון בן גמליאל הוא האומר שמשלם אף דמי הוצאה? הרי במשנה לא מפורש במה נחלקו, \u0003דלמא איפכא\u0004 \u0005[שמא ההיפך],\u0006 שתנא קמא הוא זה האומר שמשלם לו גם דמי הוצאה! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שכן \u0003כל תנא\u0004 שדבריו באו \u0003בתרא\u0004 \u0005[מאוחר],\u0006 \u0003לטפויי מילתא קא אתי\u0004 \u0005[להוסיף דברים\u0006 על מה שלפניו \u0005הוא בא],\u0006 ולפיכך יש לפרש את דברי רבן שמעון בן גמליאל כהוספה על דברי התנא הראשון.","ומקשים קושיה אחרת: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003כולה,\u0004 כל המשנה, שיטת \u0003רבן שמעון בן גמליאל היא, וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003המוכר פירות לחבירו וזרען ולא צמחו, אפילו זרע פשתן\u0004 — \u0003אינו חייב באחריותן, הא\u0004 \u0005[הרי\u0006 מכאן\u0005]\u0006 ש\u0003זרעוני גינה שאינן נאכלין\u0004 — \u0003חייב באחריותן,\u0004 אלו \u0003דברי רבן שמעון בן גמליאל, שרבן שמעון בן גמליאל אומר: זרע פשתן הוא\u0004 ש\u0003אינו חייב באחריותן, הא\u0004 \u0005[הרי\u0006 מכאן\u0005]\u0006 ש\u0003זרעוני גינה שאינן נאכלין\u0004 — \u0003חייב באחריותן,\u0004 ואם כן ממשנתנו אין להוכיח שרבן שמעון בן גמליאל חולק בענין הוצאה!","\u0003אלא\u0004 רב חסדא, שאמר שדברי \"יש אומרים\" דעת רבן שמעון בן גמליאל היא, כוונתו ל\u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003רבן שמעון בן גמליאל, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוליך חטין\u0004 לטוחן \u0003לטחון,\u0004 \u0003ולא לתתן\u0004 (לא נתנם במים לפני הטחינה כדי לרככן ולהפריד מהן את קליפתן), \u0003ועשאן\u0004 בטחינה \u0003סובין\u0004 פסולת דקה, \u0003או מורסן\u0004 שהוא קמח מעורב בפסולת גסה, של שיירי קליפות החיטים. או שנתן אדם \u0003קמח לנחתום\u0004 כדי לאפותו, \u0003ואפאו\u0004 הנחתום \u0003פת ניפולין\u0004 שמתפוררת לחתיכות. או שנתן אדם \u0003בהמה לטבח\u0004 (שוחט) לשוחטה, \u0003וניבלה\u0004 עשה אותה נבילה בשחיטתו — על כל אלה \u0003חייב\u0004 בעל המלאכה לשלם, \u0003מפני שהוא כ\u0004שומר \u0003נושא שכר\u0004 ומשלם מה שהזיק ברשלנות כזו.","\u0003רבן שמעון בן גמליאל אומר: נותן לו\u0004 גם \u0003דמי בושתו ודמי בושת אורחיו,\u0004 אם על סמך זה הזמין אורחים לסעודה, ועתה בעל המלאכה לא יכול לתת להם אוכל. \u0003וכן היה רבן שמעון בן גמליאל אומר: מנהג גדול היה בירושלים, המוסר סעודה לחברו\u0004 שיכין עבורו \u0003וקלקלה\u0004 החבר — \u0003נותן לו דמי בשתו ודמי בושת אורחיו.\u0004","ודרך אגב מוסיפים: \u0003עוד מנהג גדול היה בירושלים,\u0004 כשהיו עושים סעודה או משתה היתה \u0003מפה פרוסה על גבי הפתח, כל זמן שמפה פרוסה\u0004 — \u0003אורחין נכנסין,\u0004 שיודעים שיש מקום לסעוד שם. \u0003נסתלקה המפה\u0004 — \u0003אין האורחין נכנסין\u0004 עוד.","\u0003המוכר פירות\u0004 (מיני תבואה וכיוצא בהם) \u0003לחבירו\u0004 — \u0003הרי זה\u0004 הקונה, \u0003מקבל עליו רובע\u0004 קב של \u0003טנופת\u0004 (מיני לכלוך), \u0003ל\u0004כל \u0003סאה\u0004 מהפירות שקנה. הקונה \u0003תאנים\u0004 — \u0003מקבל עליו עשר\u0004 תאנים \u0003מתולעות ל\u0004כל \u0003מאה.\u0004 הקונה \u0003מרתף של יין\u0004 — \u0003מקבל עליו עשר\u0004 חביות \u0003קוססות\u0004 חמוצות מעט, \u0003למאה.\u0004 הקונה \u0003קנקנים בשרון\u0004 — \u0003מקבל עליו עשר פיטסות\u0004 (כדים רעים) \u0003למאה.\u0004","\u0003תאני\u0004 \u0005[שנה]\u0006 \u0003רב קטינא:\u0004 \"רובע טינופת\" שאמרו במשנה, אין הכוונה ללכלוך ממש, עפר וכיוצא בו, אלא ל\u0003רובע קטנית ל\u0004כל \u0003סאה\u0004 של פירות. ושואלים: \u0003ו\u0004כי \u0003עפרורית לא\u0004 מקבל הקונה על עצמו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר חייא קטוספאה\u0004 (מקטיספון) \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה:\u0004 מי ש\u0003בורר צרור\u0004 (אבן או עפר) ומוציא אותו \u0003מגרנו של חברו\u0004 —"],["\u0003נותן לו דמי חטין\u0004 כנגד הצרור שהוציא, שכן אם לא היה מוציא את הצרור היה חבירו מוכר את החיטים עם הצרור שבתוכן במחיר של חיטים, ועכשיו שהוציא את הצרור, הרי זה כאילו נטל ממנו חיטים באותה כמות. ומכאן שהקונה מקבל על עצמו עפרורית!","ומשיבים: צריך להבין את דברי רב קטינא כך: אם היתה \u0003קטנית\u0004 מעורבת בחיטים, ושיעורה בתוך החיטים עד \u0003רובע\u0004 — מקבל, \u0003עפרורית\u0004 — רק \u0003פחות מרובע.\u0004","ושואלים: \u0003ועפרורית רובע לא? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר פירות לחברו,\u0004 אם מכר לו \u0003חטין\u0004 — \u0003מקבל עליו\u0004 הקונה \u0003רובע קטנית לסאה.\u0004 מכר לו \u0003שעורים\u0004 — \u0003מקבל עליו רובע נישובת\u0004 (מוץ וכיוצא בזה) \u0003לסאה.\u0004 מכר לו \u0003עדשים\u0004 — \u0003מקבל עליו רובע עפרורית לסאה;\u0004","\u0003מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 ש\u0003הוא הדין לחטים ולשעורין,\u0004 שגם בהן מקבל עליו רובע עפרורית? ודוחים: אינו כן, דין זה הוא רק בעדשים ולא בחיטים ושעורים, וטעם ההבדל, \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003עדשים, דמיעקר עקרי להו\u0004 \u0005[שעוקרים אותן]\u0006 על שורשיהן מהאדמה, ולא קוצרים, ומשום כך מעורבת בהם אדמה. אבל בחיטים ושעורים, שנקצרות, לא צריכה להיות עפרורית בכמות כזו.","ומציעים: \u0003אלא\u0004 מעתה, לדבריך ש\u0003טעמא\u0004 \u0005[הטעם]\u0006 הוא משום ש\u0003עדשים דמיעקר עקרי להו\u0004 \u0005[שעוקרים אותן]\u0006 יש בהן עפר, \u0003אבל חטי ושערי\u0004 \u0005[חיטים ושעורים]\u0006 \u0003לא,\u0004 אם כן \u0003תפשוט מינה\u0004 \u0005[תפתור ממנה]\u0006 את הבעיה לצד אחר, ונאמר לגבי קניית \u0003חטי ושערי\u0004 \u0005[חיטים ושעורים]\u0006 ש\u0003עפרורית לא מקבל\u0004 עליו הקונה כלל!","ודוחים: \u0003לעולם\u0004 תפרש ש\u0003חטי ושערי\u0004 \u0005[חיטים ושעורים]\u0006 גם כן \u0003מקבל\u0004 עליו הקונה \u0003עפרורית\u0004 בשיעור רובע, אלא \u0003עדשים איצטריכא ליה\u0004 \u0005[נצרכה לו\u0006 לומר\u0005],\u0006 משום \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003כיון דמיעקר עקרי להו\u0004 \u0005[שעוקרים אותם]\u0006 ויש בהם עפר מרובה, אם כן \u0003יותר מרובע\u0004 עפרורית \u0003נמי לקבל\u0004 \u0005[גם כן יקבל]\u0006 עליו הקונה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שרק רובע מקבל עליו ולא יותר.","ובענין זה \u0003אמר רב הונא:\u0004 למרות שהקונה מקבל עליו טינופת בשיעור מסויים ואינו יכול להוציאה מן החשבון, \u0003אם בא\u0004 הקונה ורוצה \u0003לנפות\u0004 את מה שקנה כדי לבדוק כמה פסולת יש שם, ומצא שיש שם יותר מן השיעור המותר — \u0003מנפה את כולו\u0004 והמוכר חייב להשלים את כל החסר בחיטים או בכסף, ולא רק מה שייתר על רובע. והלכה זו, \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהיא \u0003דינא\u0004 \u0005[\u0006מצד ה\u0005דין],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיא משום \u0003קנסא\u0004 \u0005[קנס].\u0006","ומפרטים: \u0003אמרי לה דינא\u0004 \u0005[יש אומרים\u0006 שהיא \u0005דין],\u0006 שהם סבורים כי \u0003מאן דיהיב זוזי\u0004 \u0005[מי שנותן כסף]\u0006 לקנות — \u0003אפירי שפירי יהיב\u0004 \u0005[\u0006\u0005על פירות יפים,\u0006 בלא כל פסולת, הוא \u0005נותן],\u0006 \u0003ו\u0004מדוע בכל זאת הוא מקבל עליו רובע? כי ב\u0003רובע לא טרח איניש\u0004 \u0005[אין אדם טורח],\u0006 והוא מעדיף לקבל רובע פסולת מאשר לטרוח ולנפות את כל הפירות עד שיקבל פירות יפים בלבד. ואולם על מנת שלא יהיה \u0003יותר מרובע\u0004 פסולת כן \u0003טרח איניש\u0004 \u0005[טורח אדם],\u0006 \u0003וכיון דטרח\u0004 \u0005[שטורח]\u0006 לנפות — \u0003טרח בכוליה\u0004 \u0005[טורח בכל]\u0006 עד שיהיו לו פירות יפים בלא פסולת כלל.","\u0003ואמרי לה קנסא\u0004 \u0005[ויש אומרים\u0006 שמנפה את כולו משום \u0005קנס],\u0006 שהם סבורים כי לגבי פסולת \u0003רובע שכיח\u0004 \u0005[מצוי],\u0006 ומתחילה לשם כך אדם נותן את כספו, \u0003יותר\u0004 מרובע \u0003לא שכיח\u0004 \u0005[מצוי],\u0006 \u0003ואיהו\u0004 \u0005[והוא]\u0006 המוכר \u0003הוא דעריב\u0004 \u0005[ש\u0006הוסיף ו\u0005עירב]\u0006 פסולת יותר מרובע, \u0003וכיון דעריב\u0004 \u0005[שעירב]\u0006 — \u0003קנסוהו רבנן בכוליה\u0004 \u0005[חכמים בכל]\u0006 שישלים ויפצה את הלוקח בכל הפסולת כולה.","\u0003(סימן\u0004 לשש הלכות שתבאנה לענין דברי רב הונא: \u0003כל תרי שטרי דראבין בר רב נחמן אונאה וקבלנותא).\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב הונא ממה ששנינו במשנה בדיני כלאיים: \u0003כל סאה\u0004 זרעים \u0003שיש בה רובע ממין אחר\u0004 ובא לזורעה — \u0003ימעט\u0004 בעל השדה אותו מין אחר, כדי שלא יהיה בשדה שזורע בו זרעים אלה שיעור של רובע לסאה, ויעבור בכך על איסור כלאיים. \u0003סברוה\u0004 \u0005[חשבו,\u0006 הניחו\u0005]\u0006 הלומדים, כי דינו של \u0003רובע\u0004 ממין אחר לענין \u0003כלאים\u0004 הריהו \u0003כ\u0004דינו של \u0003יותר מרובע דהכא\u0004 \u0005[של כאן]\u0006 לענין מיקח, שהוא אסור, \u0003וקא תני\u0004 \u0005[ושנה\u0006 בענין כלאיים\u0005]:\u0006 \u0003ימעט\u0004 עד פחות מרובע, שאף שבורר ומוציא מן הזרע המעורב — אינו צריך להוציא את כולו אלא רק מקצתו, עד שיהא פחות מרובע. ומדוע, אם כן, אמר רב הונא שלענין מיקח צריך להוציא כל התערובת כולה?","ודוחים: \u0003לא, רובע\u0004 של \u0003כלאים כי\u0004 \u0005[כמו]\u0006 \u0003רובע דהכא דמי\u0004 \u0005[של כאן נחשב],\u0006 ואף בכלאיים, אם היה יותר מרובע ממין אחר —","חייב להוציא הכל. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין הדינים נבדלים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ימעט\u0004 כאשר יש רובע בלבד, הרי אינו עובר משום כלאיים על תערובת זו! ומשיבים: \u0003משום חומרא\u0004 שבעניינם של \u0003כלאים.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006"],["\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה,\u0006 המשכה של משנה זו\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 לא די שממעט עד רובע, אלא \u0003יבור\u0004 (יברור) את כל המין האחד שהתערב.","ומעתה יש לשאול: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שרובע לענין כלאיים \u0003כיותר מרובע טנופת\u0004 לענין מכירה \u0003דמי\u0004 \u0005[נחשב],\u0006 ניתן לומר כי \u0003בהא קא מיפלגי\u0004 \u0005[ב\u0006נושא \u0005זה הם חלוקים],\u0006 ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003לא קנסינן התירא אטו איסורא\u0004 \u0005[אין אנו קונסים בהיתר משום האיסור],\u0006 ולכן רק ימעט לכדי פחות מרובע. \u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003קנסינן\u0004 \u0005[קונסים אנו]\u0006 היתר משום האיסור, ולכן צריך לברור הכל, וכדברי רב הונא. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שרובע לענין כלאיים \u0003כרובע\u0004 לענין מכירה \u0003דמי\u0004 \u0005[נחשב]\u0006 ומעיקר הדין אין צורך אפילו למעט, \u0003אמאי\u0004 \u0005[מדוע]\u0006 לדעת ר' יוסי \u0003יבור\u0004 הכל?","ומשיבים: \u0003התם היינו טעמא\u0004 \u0005[שם\u0006 בכלאיים \u0005זהו הטעם]\u0006 של \u0003ר' יוסי, משום דמיחזי כי\u0004 \u0005[שנראה כמו]\u0006 \u0003מקיים כלאים,\u0004 כאשר מתחיל לברור ולמעט, ומניח מרצונו רובע של זרע אחר.","ומציעים עוד ראיה בענין דינו של רב הונא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003שנים שהפקידו\u0004 כסף \u0003אצל אחד, זה\u0004 הפקיד \u0003מנה\u0004 (מאה דינרים) \u0003וזה מאתים,\u0004 והנפקד אינו זוכר מי נתן לו את המאתים ומי נתן לו את המאה, \u0003זה אומר \"מאתים שלי\", וזה אומר \"מאתים שלי\"\u0004 — \u0003נותן לזה מנה ולזה מנה, והשאר יהא מונח עד שיבא אליהו,\u0004 ואין קונסים את הרמאי שלא יקבל כלום. ואם כן, אף בענין מכירה ביותר מרובע אין לנו לקנוס את המוכר על הכל!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003ודאי\u0004 מגיע \u0003מנה למר\u0004 \u0005[לזה]\u0006 \u0003ומנה למר\u0004 \u0005[לזה],\u0006 ובזה אין ספק כלל, \u0003הכא, מי יימר דלאו כוליה ערובי עריב\u0004 \u0005[כאן, מי יאמר שלא\u0006 את \u0005הכל עירב\u0006 המוכר בידיים\u0005]?\u0006 ואין ודאות שאפילו חלק מן הפסולת הגיע לשם בהיתר.","ומציעים עוד, \u0003תא שמע מסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 כשיטתו של רב הונא \u0005מ\u0006מה ששנינו ב\u0005סופה,\u0006 המשכה של אותה משנה\u0005],\u0006 \u0003אמר ר' יוסי: אם כן\u0004 שכל אחד מהמפקידים מקבל מנה, \u0003מה\u0004 אם כן \u0003הפסיד הרמאי? אלא הכל יהא מונח עד שיבא אליהו,\u0004 משמע שלדעת ר' יוסי קונסים היתר משום איסור, והרי זה ראיה לדעת רב הונא.","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במפקידים \u0003ודאי איכא\u0004 \u0005[יש]\u0006 \u0003רמאי,\u0004 שהרי רק אחד מהם הפקיד מאתיים, ולפיכך יש מקום לקנוס כדי שהעבריין ייענש, \u0003הכא מי יימר דערובי עריב\u0004 \u0005[כאן,\u0006 במכירה \u0005מי יאמר ש\u0006הוא \u0005עירב\u0006 כלל\u0005]\u0006 ולכן אין זה מוכח שצריך לקנוס אותו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדברי רב הונא ממה ששנינו בברייתא: \u0003שטר\u0004 הלוואה \u0003שיש בו רבית\u0004 — \u0003קונסין אותו\u0004 את המלווה בעל השטר, \u0003ואינו גובה\u0004 בשטר זה \u0003לא את הקרן ולא את הרבית,\u0004 אלו \u0003דברי ר' מאיר,\u0004 והרי זו ראיה לדעת רב הונא!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בריבית \u0003משעת\u0004 ה\u0003כתיבה\u0004 של השטר \u0003הוא דעבד ליה שומא\u0004 \u0005[שעשה לו הערכה]\u0006 אומדן וקביעה כמה ריבית יהא חייב לו, כלומר, העבירה של ריבית כבר נעשתה בזמן כתיבת השטר, ולכן קונסים את המלווה על עבירה שוודאי עבר, \u0003הכא מי יימר דערובי עריב\u0004 \u0005[כאן,\u0006 במכירה \u0005מי יאמר ש\u0006המוכר עבר ו\u0005עירב]\u0006 את הפסולת, ואין משם הוכחה שיש לקנוס אותו כאן.","ומציעים עוד ראיה, \u0003תא שמע מסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע מ\u0006מה ששנינו ב\u0005סופה,\u0006 המשכה של אותה ברייתא\u0005],\u0006 \u0003וחכמים אומרים: גובה את הקרן ואינו גובה את הרבית,\u0004 ומכאן משמע שאין קונסים, והרי זה שלא כדעת רב הונא!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם\u0006 בשטר ריבית\u0005]\u0006 \u0003ודאי קרנא דהתירא\u0004 \u0005[הקרן,\u0006 סכום הכסף שלווה ממנו \u0005של היתר]\u0006 \u0003הוא, הכא מי יימר דכוליה\u0004 \u0005[כאן, מי יאמר ש\u0006את \u0005כולו,\u0006 כל הפסולת\u0005]\u0006 \u0003לא ערובי עריב\u0004 \u0005[עירב\u0006 המוכר\u0005],\u0006 ולפיכך יש מקום לומר שיקנסוהו על הכל.","ומציעים עוד ראיה לשיטת רב הונא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבין בר רב נחמן\u0004 ברייתא זו: כאשר אדם מוכר שדה לחבירו, ואומר לו שמוכר שטח גדול, כגון בית כור \"הן חסר הן יתר\", כלומר, בערך, שנינו במשנה כי כל עוד אין ההפרש גדול יותר מבית רובע לכל בית סאה (אחד לעשרים וארבע) המיקח קיים כפי שהוא. אבל אם נמצא שהיה ההבדל גדול יותר מרובע לסאה, צריך המוכר להחזיר לקונה. ועל כך אמרו באותה ברייתא: \u0003לא את המותר\u0004 (יותר מבית רובע לבית סאה) \u0003בלבד הוא מחזיר, אלא מחזיר לו\u0004 גם \u0003את כל הרבעין כולן\u0004 רבע לבית סאה, שעכשיו צריך להחזיר במידה מדוייקת לגמרי; \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 ש\u0003היכא דבעי אהדורי\u0004 \u0005[במקום שצריך להחזיר]\u0006 — \u0003כולה מהדר\u0004 \u0005[\u0006את \u0005הכל\u0006 הוא \u0005מחזיר]\u0006 והוא ממש כדברי רב הונא!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006"],["\u0003התם\u0004 \u0005[שם\u0006 במכירת בית הכור\u0005]\u0006 אמנם \u0003\"הן חסר הן יתיר\" אמר ליה\u0004 \u0005[לו]\u0006 לקונה, \u0003מיהו\u0004 \u0005[מכל מקום]\u0006 דווקא עד \u0003רביע ל\u0004\u0003א חשיב\u0004 \u0005[חשוב],\u0006 ולכן נכלל באותה הסתייגות, אבל \u0003יתר מרביע חשיב\u0004 \u0005[חשוב],\u0006 ש","\u0003כיון דחזי ליה לאיצטרופי\u0004 \u0005[שראוי לו להצטרף]\u0006 \u0003בתשעת קבין,\u0004 שקצת יותר מרובע הקב לסאה מצטרף בבית כור (שלושים סאים) עד לבית תשעה קבים, וקרקע בת תשעת קבים \u0003הויא לה ארעא חשיבתא באפי נפשא והדרא\u0004 \u0005[הריהי קרקע חשובה בפני עצמה ו\u0006לכן היא \u0005חוזרת].\u0006 אבל אין ללמוד מכאן ליתר מרובע טינופת בסאה, שאין היא חשובה לעצמה.","ומציעים עוד ראיה לדברי רב הונא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003האונאה,\u0004 שהונה מוכר את הקונה (או להיפך), והיה התשלום לא כפי ערך הדבר הנמכר, אם היה ההבדל בין הסכום שניתן לשוויו האמיתי \u0003פחות משתות\u0004 (שישית) — \u0003נקנה\u0004 ה\u0003מקח,\u0004 ונמחלת האונאה, \u0003יותר משתות\u0004 — \u0003בטל\u0004 ה\u0003מקח\u0004 לגמרי. אם היה ההבדל \u0003שתות\u0004 בדיוק — \u0003קנה ומחזיר\u0004 זה שהונה את ה\u0003אונאה.\u0004","ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 מחזיר בדיוק בשישית את כל סכום האונאה? \u0003ליהדר\u0004 \u0005[שיחזיר]\u0006 רק \u0003עד פחות משתות,\u0004 שהרי בפחות משישית נמחלת האונאה! \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כל היכי דבעי לאהדורי\u0004 \u0005[מקום שצריך להחזיר]\u0006 — \u0003כולה מהדר\u0004 \u0005[את הכל\u0006 הוא \u0005מחזיר]\u0006 ואיננו משייר, ובדומה לדברי רב הונא!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם מעיקרא\u0004 \u0005[שם,\u0006 באונאה, \u0005מתחילה]\u0006 \u0003שוה בשוה אמר ליה\u0004 \u0005[לו],\u0006 הכוונה היתה שיימכר המיקח בדיוק בשוויו, \u0003מיהו\u0004 \u0005[ואולם]\u0006 אונאה בשיעור \u0003פחות משתות\u0004 — \u0003לא ידיעה\u0004 \u0005[ידועה],\u0006 אינה ניכרת \u0003במנה, ומחיל איניש\u0004 \u0005[ומוחל אדם]\u0006 על הבדל זה. \u0003שתות\u0004 — \u0003ידיעה, ולא מחיל איניש\u0004 \u0005[ידועה,\u0006 ניכרת, \u0005ואין אדם מוחל].\u0006 \u0003יתר משתות\u0004 — \u0003מקח טעות הוא ובטל מקח.\u0004 אבל בפסולת שבפירות, הכל יודעים שיש מעט פסולת בפירות, ומראש מקבל על עצמו הקונה פסולת זו.","ומציעים עוד ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003המקבל שדה מחברו ליטע\u0004 אותה תמורת שכר מסויים — \u0003הרי זה\u0004 המזמין את העבודה \u0003מקבל עליו עשר בוריות\u0004 (אילנות שאינם עושים פרי) \u0003ל\u0004כל \u0003מאה,\u0004 שלא הכל מצמיח פרי. היו הבוריות \u0003יותר מכאן\u0004 מעשר למאה — \u0003מגלגלין עליו את הכל\u0004 ונוטע מחדש את כל האילנות שלא הצליחו. משמע שאם מחזיר —","מחזיר הכל, וכדברי רב הונא! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 במקרה זה אין ראיה, שכן \u0003כל יתר מכאן\u0004 מעשר למאה, הרי זה \u0003כבא ליטע מתחלה דמי\u0004 \u0005[נחשב],\u0006 שהרי זה כאילו נותר שדה שלם שלא נטעו עדיין, וכיון שבא לנטוע מתחילה, ודאי שצריך לנטוע את השדה כראוי ולא להשאיר אילנות לא ראויים. אבל בפחות מעשרה — אין זה נחשב כנטיעה של שדה שלם, ואפשר לומר שמוחל. ואולם במכירה, כאשר יש יותר מרובע טינופת לסאה, אינו חשוב לעצמו כל כך.","שנינו במשנה שהקונה \u0003מרתף של יין\u0004 מקבל עליו עשר חביות קוססות (חמוצות מעט) למאה. ומתקשים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה המכר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מרתף של יין\" סתם\u0004 — \u0003קשיא\u0004 \u0005[קשה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מרתף זה של יין\"\u0004 — \u0003קשיא\u0004 \u0005[קשה].\u0006","ומפרטים: \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מרתף זה\"\u0004 — \u0003קשיא\u0004 \u0005[קשה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"מרתף של יין אני מוכר לך\"\u0004 — הרי זה \u0003נותן לו יין שכולו יפה.\u0004 אמר לו \u0003\"מרתף זה של יין אני מוכר לך\"\u0004 — \u0003נותן לו יין הנמכר בחנות,\u0004 כלומר, שהוא חמוץ קצת (קוסס), ואפילו כולו היה כזה. ואם אמר לו \u0003\"מרתף זה אני מוכר לך\"\u0004 ולא פירש שהוא יין — \u0003אפילו\u0004 היה \u0003כולו חומץ הגיעו\u0004 (כך מקבל אותו) הקונה, ואינו יכול לחזור בו. ואם כן דין משנתנו אינו מתאים לאף אחד מהמקרים הללו!","ומסבירים: \u0003לעולם\u0004 מדובר במשנתנו ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר לקונה \u0003\"מרתף של יין\" סתם, ותני ברישא\u0004 \u0005[ושנה בראשה ]\u0006 של ה\u0003ברייתא\u0004 ששנינו בה שנותן לו יין שכולו יפה, והוסף: \u0003ומקבל עליו עשר קוססות למאה.\u0004","ושואלים: \u0003ובסתם מי\u0004 \u0005[האם]\u0006 \u0003מקבל\u0004 עליו הקונה קוססות? \u0003והא תאני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: המוכר חבית יין לחברו\u0004 — \u0003נותן לו יין שכולו יפה!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חבית, דכולא חד חמרא\u0004 \u0005[שכל\u0006 היין שבתוכה \u0005יין אחד]\u0006 \u0003הוא\u0004 ולכן אינו יכול לתת לו יין שיהא מקצתו חמוץ מעט.","על העמדה זו של משנתנו מקשים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב זביד\u0004 ברייתא \u0003דבי\u0004 \u0005[של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' אושעיא:\u0004 אם אמר \u0003\"מרתף של יין אני מוכר לך\"\u0004 — \u0003נותן לו יין שכולו יפה, \"מרתף זה של יין אני מוכר לך\"\u0004 — \u0003נותן לו יין שכולו יפה,\u0004 אבל \u0003מקבל עליו עשר קוססות למאה,\u0004"],["\u0003וזהו\u0004 דין \u0003אוצר\u0004 (מרתף) \u0003ששנו חכמים במשנתינו,\u0004 ולא כפי שהעמדנו קודם, במרתף של יין סתם!","\u0003אלא\u0004 יש לחזור מההסבר הקודם וכך יש לומר: \u0003מתניתין נמי\u0004 \u0005[משנתנו גם כן]\u0006 מדברת באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"זה\".\u0004","ומקשים: אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מה שאמרנו בברייתא אחת בענין \"מרתף \u0003זה\"\u0004 על \u0003\"זה\"\u0004 שבברייתא האחרת, שבברייתא הראשונה נאמר שנותן לו מן הנמכר בחנות, כלומר אפילו כולו קוסס, ואילו בברייתא שהביא רב זביד — רק עשר מתוך מאה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 שהוא צריך יין \u0003למקפה\u0004 לצורך תבשיל, ולשם כך צריך יין משובח, \u0003הא\u0004 \u0005[זו]\u0006 — ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה.\u0004 ומסבירים: אותה ששנה \u0003רב זביד\u0004 שמקבל עליו רק עשר קוססות, מדובר במקרה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה,\u0004 ואז צריך לתת לו יין שכולו טוב, ב\u0003ברייתא\u0004 מדובר באופן ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה,\u0004 ומשום שאמר \"מרתף זה של יין\" — הקונה מקבל עליו כל יין שיהא שם.","\u0003הלכך\u0004 \u0005[על כן]\u0006 סיכום הדברים לשיטת רב זביד: אמר לו \u0003\"מרתף של יין\" ואמר לו למקפה\u0004 — \u0003נותן לו יין שכולו יפה; \"מרתף זה של יין\" ואמר ליה\u0004 שהוא צריך אותו \u0003למקפה\u0004 — \u0003נותן לו יין שכולו יפה, ו\u0004אולם משום שאמר גם \"זה\" — \u0003מקבל עליו עשר קוססות למאה;\u0004 אמר לו \u0003\"מרתף זה של יין\" ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה\u0004 — \u0003נותן לו יין הנמכר בחנות,\u0004 כלומר, אף שכולו קוססות.","בעקבות סיכום זה, בו נוסף עוד מרכיב קובע, והוא: האם יין זה מיועד למקפה או לא, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 אמר לו \u0003\"מרתף של יין\"\u0004 ולא אמר \"זה\", \u0003ו\u0004אולם גם \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה, מאי\u0004 \u0005[מה]\u0006 יהא דינו? האם מקבל עליו הקונה עשר קוססות, מאחר שלא פירש למקפה, או מאחר ומדובר היה על מרתף של יין, ולאו דווקא זה — זכותו לדרוש יין שכולו טוב? \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מקבל\u0004 הלוקח עשר קוססות למאה, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: לא מקבל.\u0004","ומסבירים את טעמיהם: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ש\u0003מקבל\u0004 הוא \u0003דייק מ\u0004הברייתא שהביא \u0003רב זביד, דקתני\u0004 \u0005[ששנה]:\u0006 \u0003\"מרתף של יין אני מוכר לך\"\u0004 — \u0003נותן לו יין שכולו יפה, ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו את הברייתא במקרה\u0005]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה,\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא משום ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה, הא\u0004 \u0005[אבל]\u0006 אם \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה\u0004 — \u0003מקבל\u0004 עשר קוססות.","\u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 ש\u0003לא מקבל\u0004 — הוא \u0003דייק מ\u0004דברי ה\u0003ברייתא\u0004 האחרת, \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003\"מרתף של יין אני מוכר לך\"\u0004 — \u0003נותן לו יין שכולו יפה, ואוקימנא\u0004 \u0005[והעמדנו]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה.\u0004","ושואלים: \u0003ולמאן\u0004 \u0005[ולמי]\u0006 ש\u0003דייק מ\u0004דברי \u0003רב זביד, קשיא\u0004 \u0005[קשה]\u0006 איפוא ה\u0003ברייתא!\u0004 ומשיבים: לשיטתו \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך שנה\u0006 אותה\u0005]:\u0006 \"מרתף של יין אני מוכר לך\" — נותן לו יין שכולו יפה. \u0003במה דברים אמורים\u0004 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה, הא\u0004 \u0005[אבל]\u0006 אם \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה\u0004 — \u0003מקבל\u0004 עשר קוססות. \u0003ו\u0004אם אמר לו \u0003\"מרתף זה של יין\" ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה\u0004 — \u0003נותן לו יין הנמכר בחנות.\u0004","ושואלים לצד האחר: \u0003ולמאן\u0004 \u0005[ולמי]\u0006 ש\u0003דייק מ\u0004דברי ה\u0003ברייתא קשיא\u0004 \u0005[קשה]\u0006 מן הברייתא שהביא \u0003רב זביד, דאוקימנא\u0004 \u0005[שהעמדנו]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003לא אמר ליה למקפה\u0004 — \u0003מקבל\u0004 עשר קוססות!","ומשיבים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה\u0004 גם כן \u0003לא מקבל, והאי דאוקימנא\u0004 \u0005[וזה שהעמדנו]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למקפה, משום דקשיא\u0004 \u0005[שהיה קשה]\u0006 \u0003\"זה\"\u0004 על \u0003\"זה\"\u0004 מן המקרה האחר, כשאמר \"זה\", על המקרה שאמר \"זה\" בברייתא שהביא רב זביד.","אגב שהוזכר בסוגיה יין הנמכר בחנות דנים בעניינו. \u0003אמר רב יהודה: יין הנמכר בחנות\u0004 — \u0003מברכין עליו \"בורא פרי הגפן\",\u0004 שאף על פי שאינו יין משובח — עדיין בגדר יין הוא. \u0003ורב חסדא אמר: גבי חמרא דאקרים\u0004 \u0005[אצל יין שהקרים\u0006 שהחמיץ, שהתקלקל\u0005]\u0006 \u0003למה לי?\u0004 ויברך עליו \"שהכל\".","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב יהודה ממה ששנינו בברייתא העוסקת בברכות: \u0003על\u0004 דברי מאכל ומשתה שהתקלקלו, כגון \u0003הפת שעפשה, ועל היין שהקרים, ועל תבשיל שעברה צורתו\u0004 — \u0003אומר \"שהכל נהיה בדברו\",\u0004 משמע מכאן שאין מברכים על יין הנמכר בחנות \"בורא פרי הגפן\"!","\u0003אמר רב זביד: מודה רב יהודה בפורצמא דמיזדבן אקרנתא\u0004 \u0005[ביין גרוע שנמכר בקרנות\u0006 הרחוב\u0005]\u0006 שעליו אין מברכים \"בורא פרי הגפן\", ולדעתו בו עוסקת הברייתא. אבל היין הנמכר בחנות משובח ממנו, ועדיין הוא בגדר יין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[הרי]\u0006 דעת \u0003רב יהודה, הא\u0004 \u0005[הרי]\u0006 דעת \u0003רב חסדא, מר כמאן סבירא ליה\u0004 \u0005[אדוני כמי הוא סבור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתא ידענא\u0004 \u0005[ברייתא אני יודע]\u0006 ועליה אני סומך."],["\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הבודק את החבית\u0004 אם היא מכילה יין טוב, על מנת \u0003להיות מפריש עליה תרומה והולך,\u0004 שמחבית זו יפריש תרומה עבור חביות אחרות של יין, כאשר יצטרך להפריש מהן תרומה, \u0003ואחר כך,\u0004 לאחר שהפריש כמה פעמים מחבית זו, \u0003נמצאת חומץ,\u0004 ואין מפרישים תרומה ומעשרות מן החומץ על היין, ומעתה יש לדון על כל ההפרשות שהיו מאז הבדיקה הראשונה ועד עתה, \u0003כל שלשה יום\u0004 — \u0003ודאי, מכאן ואילך\u0004 — \u0003ספק.\u0004","תחילה מבררים מהן האפשרויות השונות בפירוש הברייתא, ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]\u0006 לאלו ימים הכוונה ב\"כל שלושה ימים\"? \u0003אמר ר' יוחנן, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003כל שלשה ימים הראשונים\u0004 מאז שבדק בתחילה, החבית נחשבת כ\u0003ודאי יין, מכאן ואילך ספק\u0004 יין ספק חומץ;","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003חמרא מעילאי עקר\u0004 \u0005[היין\u0006 שבחבית \u0005מלמעלה\u0006 הוא \u0005מחמיץ\u0006 תחילה\u0005],\u0006 \u0003והאי טעימיה\u0004 \u0005[וזה\u0006 הבעלים הרי \u0005טעם אותו]\u0006 בתחילה, \u0003ולא עקר\u0004 \u0005[החמיץ],\u0006 ואף \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר: בתר דטעימיה עקר\u0004 \u0005[אחר שטעם אותו\u0006 אז \u0005החמיץ],\u0006 כלומר, מיד אחר כך, מכל מקום הרי אין היין מחמיץ מיד, ומתחילה כל שלושה ימים הראשונים \u0003הוה ריחא חלא וטעמיה חמרא\u0004 \u0005[היה ריחו חומץ וטעמו יין],\u0006 \u0003וכל ריחיה חלא וטעמיה חמרא\u0004 \u0005[\u0006ש\u0005ריחו חומץ וטעמו יין]\u0006 — \u0003חמרא\u0004 \u0005[יין\u0006 הוא\u0005].\u0006","\u0003ור' יהושע בן לוי אמר\u0004 שיש לפרש כך את הברייתא: \u0003כל שלשה ימים האחרונים\u0004 לפני שמצא שהוא חומץ — \u0003ודאי חומץ\u0004 הוא, שלשיטתו יין שהחל להריח כחומץ, הגם שטעמו עדיין של יין — חומץ הוא, ואם עכשיו הוא חומץ גמור ודאי החל להחמיץ לפני שלושה ימים. \u0003מכאן ולהלן,\u0004 כלומר, כל הימים הקודמים לכך מאז הבדיקה הראשונה — \u0003ספק;\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003חמרא מתתאי עקר\u0004 \u0005[היין\u0006 בחבית \u0005מלמטה\u0006 הולך ו\u0005מחמיץ],\u0006 \u0003ואימור עקר ולאו אדעתיה\u0004 \u0005[ואמור\u0006 שכשבדק בתחילה כבר \u0005החמיץ ולא היה\u0006 הדבר \u0005בדעתו,\u0006 במודעותו\u0005]\u0006 שהרי טעם רק מלמעלה. \u0003ו\u0004גם \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003מעילאי עקר והא טעימיה\u0004 \u0005[שמלמעלה\u0006 הוא \u0005מחמיץ וזה\u0006 הרי \u0005טעם אותו]\u0006 \u0003ולא עקר\u0004 \u0005[החמיץ]\u0006 — \u0003דלמא בתר דטעימיה עקר\u0004 \u0005[שמא\u0006 מיד \u0005אחר שטעם אותו\u0006 אז \u0005החמיץ],\u0006 \u0003הוה ריחיה חלא וטעמיה חמרא\u0004 \u0005[נמצא\u0006 שמאז \u0005ריחו חומץ וטעמו יין],\u0006 \u0003ו\u0004לשיטתו של ר' יהושע בן לוי, כל יין ש\u0003ריחיה חלא וטעמיה חמרא\u0004 \u0005[ריחו חומץ וטעמו יין]\u0006 — \u0003חלא\u0004 \u0005[חומץ\u0006 הוא\u0005].\u0006","\u0003דרומאי\u0004 \u0005[חכמי הדרום]\u0006 \u0003מתנו משמיה\u0004 \u0005[היו שונים משמו]\u0006 של \u0003ר' יהושע בן לוי\u0004 באופן אחר: שלושה ימים \u0003ראשונים\u0004 — \u0003ודאי יין,\u0004 שלושה ימים \u0003אחרונים\u0004 — \u0003ודאי חומץ,\u0004 כל הימים ה\u0003אמצעיים\u0004 — \u0003ספק.\u0004","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה]\u0006 מתוך עצמה, \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 כי שלושה ימים \u0003ראשונים ודאי יין, אלמא ריחיה חלא וטעמיה חמרא\u0004 \u0005[מכאן\u0006 שמה ש\u0005ריחו חומץ וטעמו יין]\u0006 — \u0003חמרא\u0004 \u0005[יין\u0006 הוא\u0005],\u0006 \u0003והדר אמרת\u0004 \u0005[ו\u0006אחר כך \u0005חוזר ואומר אתה]:\u0006 שלושה ימים \u0003אחרונים ודאי חומץ, אלמא ריחיה חלא וטעמיה חמרא\u0004 \u0005[מכאן\u0006 שמה ש\u0005ריחו חומץ וטעמו יין]\u0006 — \u0003חלא\u0004 \u0005[חומץ\u0006 הוא\u0005]!\u0006 ומשיבים: בעיקרו של דבר, ריחו חומץ וטעמו יין — עדיין יין הוא. ומדוע שלושה ימים האחרונים ודאי חומץ הוא?","מדובר \u0003כגון דאשתכח חלא סיפתקא\u0004 \u0005[שנמצא\u0006 בבדיקה האחרונה \u0005חומץ חריף],\u0006 \u0003דאי לאו דעקר תלתא יומי\u0004 \u0005[שאם לא שהחמיץ\u0006 אף בטעמו כבר \u0005שלושה ימים]\u0006 — \u0003לא הוה משתכח חלא סיפתקא\u0004 \u0005[היה נמצא חומץ חריף].\u0006","עד כאן עסקנו בהסברים השונים לברייתא, ומעתה שואלים: רב יוסף, שהסתמך על ברייתא זו, לפתור בעיית הברכה על יין שריחו כחומץ, \u0003כמאן פשט ליה\u0004 \u0005[כמי פתר לו]\u0006 לאביי? שהרי רק אמר לו באופן סתמי שיש פתרון לדבר מן הברייתא. \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב מרי ורב זביד, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כר' יוחנן\u0004 פתר לו, שעדיין יין הוא ומברך \"הגפן\". \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כר' יהושע בן לוי\u0004 פתר לו שחומץ הוא ומברך \"שהכל\". ואגב כך מובאת מחלוקת אמוראים בענין דומה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המוכר חבית יין לחברו והחמיצה\u0004 — \u0003אמר רב: כל שלשה ימים הראשונים\u0004 לאחר המכירה נחשב עדיין \u0003ברשות\u0004 ה\u0003מוכר,\u0004 כלומר, עליו האחריות, שחזקה שכבר החל להחמיץ קודם למכירה, וחייב לתת לקונה יין אחר תחתיו. \u0003מכאן ואילך\u0004 — \u0003ברשות\u0004 ה\u0003לוקח\u0004 ואין הלוקח יכול לטעון דבר;"],["\u0003ושמואל אמר: חמרא אכתפא דמאריה שוואר\u0004 \u0005[יין על כתפו של אדוניו קופץ,\u0006 ממהר להחמיץ\u0005],\u0006 שלאחר שטלטלו הקונה הריהו ממהר להחמיץ בגלל הטלטול, ואין המוכר נושא באחריות גם בימים הראשונים שלאחר המכירה.","ומסופר: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב יוסף עובדא כוותיה\u0004 \u0005[\u0006פסק הלכה ל\u0005מעשה כשיטתו]\u0006 של \u0003רב בשיכרא\u0004 \u0005[בשיכר],\u0006 \u0003וכוותיה\u0004 \u0005[וכשיטתו]\u0006 של \u0003שמואל בחמרא\u0004 \u0005[ביין].\u0006 ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003שמואל.\u0004","ועוד בענין דומה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד שכר תמרים, ואחד שכר שעורים, ואחד שמרי יין\u0004 שהוסיף עליהם מים עד שנעשו המים כיין — כולם \u0003מברכין עליהם\u0004 \u0003\"שהכל נהיה בדברו\",\u0004 ולא \"בורא פרי העץ\" (בשכר תמרים), או \"בורא פרי האדמה\" (בשכר שעורים), או \"בורא פרי הגפן\" בשמרים. \u0003אחרים אומרים: שמרים שיש בהם טעם יין\u0004 — \u0003מברך עליהן \"בורא פרי הגפן\",\u0004 עד כאן דברי הברייתא. ומסופר: \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין הלכה כאחרים.\u0004","\u0003אמר רבא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בברייתא, אם \u0003רמא תלתא\u0004 \u0005[הטיל,\u0006 שפך \u0005שלוש]\u0006 מידות של מים על השמרים, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ארבעה\u0004 שנתמצתה מתוך השמרים עוד מידה אחת כזו — \u0003חמרא\u0004 \u0005[יין]\u0006 \u0003הוא,\u0004 לפי שהנוסף מן השמרים הוא יין נקי, ומזוג במים שהכניסו בו. ומעירים: \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: כל חמרא\u0004 \u0005[יין]\u0006 ש\u0003לא דרי על חד תלת מיא\u0004 \u0005[נושא על\u0006 חלק \u0005אחד\u0006 של יין \u0005שלוש\u0006 מידות \u0005מים]\u0006 — \u0003לאו חמרא הוא\u0004 \u0005[אינו יין].\u0006","ומוסיף רבא: אם \u0003רמא תלתא ואתא תלתא\u0004 \u0005[הטיל שלוש\u0006 מידות מים \u0005ובא,\u0006 יצאו \u0005שלוש],\u0006 לדעת כולם — \u0003ולא כלום הוא\u0004 שבוודאי אין זה יין, אלא המים שנכנסו הם אותם שיצאו. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 בברייתא, הרי זה במקרה \u0003דרמא תלתא ואתא תלתא ופלגא\u0004 \u0005[שהטיל שלוש\u0006 מידות מים \u0005ובא,\u0006 יצאו, \u0005שלוש וחצי\u0006 מידות\u0005],\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003תלתא עייל תלתא נפיק\u0004 \u0005[שלוש נכנסו שלוש יצאו],\u0006 \u0003פש ליה פלגא\u0004 \u0005[נוספה לו מחצית]\u0006 שנתמצתה מן השמרים, \u0003ופלגא בשיתא פלגי מיא\u0004 \u0005[ומחצית בשישה חצאים\u0006 של \u0005מים]\u0006 \u0003ולא כלום הוא,\u0004 שמזיגה של אחד בשישה אינה נחשבת ליין, ולכן מברך \"שהכל\".","\u0003ואחרים סברי\u0004 \u0005[סבורים]:\u0006 \u0003תלתא עול\u0004 \u0005[שלוש\u0006 מידות של מים \u0005נכנסו],\u0006 \u0003תרין ופלגא נפיק\u0004 \u0005[שתים וחצי יצאו],\u0006 וחצי מידה נספגה בשמרים, \u0003פש ליה כוזא\u0004 \u0005[נשתיירה,\u0006 נוספה \u0005לו\u0006 לפיכך \u0005מידה אחת]\u0006 שלימה של יין, שהרי כפי שמדובר כאן, יש בידו שלוש וחצי מידות של משקה, \u0003וכוזא בתרי ופלגא\u0004 \u0005[ומידה אחת\u0006 יין \u0005בשתים וחצי]\u0006 של מים \u0003חמרא מעליא\u0004 \u0005[יין מעולה]\u0006 \u0003הוא.\u0004","ושואלים: \u0003ו\u0004כאשר הוציא מן השמרים \u0003ביותר מכדי מדתו\u0004 של המים שנתן, אפילו פחות משיעור זה, \u0003מי פליגי\u0004 \u0005[האם נחלקו]\u0006 בכך? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003המתמד\u0004 העושה משקה תמד על ידי שמוסיף מים לשמרי יין, \u0003ונתן מים במדה\u0004 מסויימת, \u0003ומצא\u0004 לבסוף שהמשקה שיצא היה \u0003כדי מדתו\u0004 במידה שהכניס — \u0003פטור\u0004 מלעשר אותו משקה משום שאין זה יין, \u0003ור' יהודה מחייב.\u0004 והרי \u0003עד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא בכדי מדתו, אבל ביותר מכדי מדתו לא פליגי\u0004 \u0005[נחלקו],\u0006 ואף חכמים סבורים שאם המשקה הנמצא הוא מעט יותר ממידת המים שנתן — חייב, שהוא יין!","ומשיבים: \u0003הוא הדין\u0004 ש\u0003אפילו ביותר מכדי מדתו פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003והאי דקא מיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 במשנה \u0003בכדי מדתו\u0004 ולא ביותר ממידתו, הרי זה \u0003להודיעך כחו\u0004 של \u0003ר' יהודה\u0004 עד כמה הוא מפליג לחייב במעשר, אפילו כשלא נוסף דבר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב נחמן בר יצחק מרב חייא בר אבין: שמרים\u0004 (כלומר, מים שנתן בתוך שמרים) \u0003שיש בהן טעם יין, מהו\u0004 דינם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת חמרא\u0004 \u0005[האם סבור אתה\u0006 כי \u0005יין]\u0006 \u0003הוא? קיוהא בעלמא\u0004 \u0005[חמיצות סתם\u0006 בלבד\u0005]\u0006 \u0003הוא\u0004 ולא יותר.","עוד בענין דומה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמרים של תרומה\u0004 — מחזור \u0003ראשון\u0004 שמוסיף להם מים למצות מהם את היין, \u0003ו\u0004כן \u0003שני\u0004 שנותן מים פעם שניה באותם שמרים — \u0003אסור\u0004 לישראל לשתות ממנו, כדין תרומה, \u0003ושלישי מותר\u0004 לפי שאינו אלא מים בלבד. \u0003ר' מאיר אומר: אף שלישי\u0004 יכול שיהא אסור, אם הוא \u0003בנותן טעם,\u0004 שאם יש בו טעם השמרים (היין) עדיין יש בו קדושה.","\u0003ו\u0004אם היו אלה שמרים \u0003של מעשר\u0004 דינם קל משל תרומה — מחזור \u0003ראשון אסור, שני מותר. ר' מאיר אומר: אף שני\u0004 אסור אם יש בו עדיין \u0003בנותן טעם. ו\u0004אם היו אלה שמרים \u0003של הקדש\u0004 דינם חמור מתרומה — \u0003שלישי אסור, ורביעי מותר. ר' מאיר אומר: אף רביעי\u0004 אסור אם יש בו \u0003בנותן טעם.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת כי \u0003של הקדש\u0004 — \u0003לעולם\u0004 ואפילו מרביעי והלאה \u0003אסור, ושל מעשר\u0004 — \u0003לעולם\u0004 ואפילו ראשון \u0003מותר,\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003הקדש\u0004 על \u0003הקדש,\u0004 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003מעשר\u0004 על \u0003מעשר!\u0004","ומתרצים: \u0003הקדש\u0004 על \u0003הקדש לא קשיא\u0004 \u0005[קשה],\u0006 שכן יש לחלק ולומר כי \u0003כאן\u0004 שהחמירו לאסור לעולם, מדובר ביין שנתקדש \u0003בקדושת הגוף\u0004 שהוקדש לצורך נסכים, ואילו \u0003כאן\u0004 שרביעי מותר ואין מחמירים כל כך — \u0003בקדושת דמים\u0004 שהוקדש היין על מנת למוכרו ולהשתמש בדמיו לצורך בדק הבית. \u0003מעשר\u0004 על \u0003מעשר נמי לא קשיא\u0004 \u0005[גם כן אינו קשה]\u0006 שכן יש לומר כי \u0003כאן\u0004 שהראשון אסור, מדובר \u0003במעשר ודאי, כאן\u0004 שמותר, מדובר \u0003במעשר\u0004 שמפרישים מ\u0003דמאי,\u0004 תבואה הנלקחת מעם הארץ, שהיא ספק מעושרת.","ובאותו ענין של שמרים שנתן עליהם מים, \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: כדרך שאמרו\u0004 בנתינת מים על שמרים \u0003לענין איסורן\u0004 עד מתי אוסרים השמרים את המים, כל אחד לפי דרגת חומרתו, \u0003כך אמרו לענין הכשירן,\u0004 שיכשירו אוכלים (שיהיו ראויים) לקבלת טומאה.","ושואלים: \u0003הכשירן דמאי\u0004 \u0005[של מה]?\u0006 \u0003אי דמיא\u0004 \u0005[אם של המים]\u0006 — \u0003אכשורי מכשרי\u0004 \u0005[\u0006הרי \u0005מכשירים\u0006 הם\u0005]\u0006 בכל מקרה, גם בלי שיתנם על השמרים, \u0003אי דחמרא\u0004 \u0005[אם של היין]\u0006 — הלא \u0003אכשורי מכשרי\u0004 \u0005[מכשיר\u0006 הוא\u0005]\u0006 בתור יין. ואם כן המשקה הזה בכל מקרה מכשיר אוכלים לקבל טומאה, ואין הבדל אם הוא עדיין נחשב ליין או לא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא במקרה \u0003שתמדו\u0004 את השמרים \u0003במי גשמים,\u0004 ומים אלה אינם מכשירים אוכלים מאליהם לקבל טומאה, אלא אם חשבו להשתמש בהם. אבל אם נעשו יין —","הריהו מכשיר לטומאה בלא שיחשוב עליו. ומקשים: \u0003ו\u0004הרי \u0003כיון דקא שקיל ורמי להו למנא\u0004 \u0005[ש\u0006הוא \u0005לוקח אותם,\u0006 את מי הגשמים הללו, \u0005ומטיל אותם לכלי]\u0006 שבו השמרים — הרי בכך \u0003אחשבינהו\u0004 \u0005[מחשיב אותם\u0006 בכך\u0005]\u0006 בשעת נתינתם לכלי, ואם כן מכשירים הם לטומאה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה \u0003שנתמד מאליו,\u0004 שירדו הגשמים לחבית שהיו בה שמרים.","ומקשים: \u0003ו\u0004הרי \u0003כיון דקא נגיד\u0004 \u0005[ש\u0006הוא \u0005מושך]\u0006 את המשקה הבא מן השמרים — \u0003קמא קמא אחשבינהו\u0004 \u0005[ראשון ראשון\u0006 שמוציא \u0005החשיב אותו]\u0006 ומכשיר לקבל טומאה, בין אם היה זה בפעם הראשונה או הרביעית! \u0003אמר רב פפא:\u0004 מדובר פה \u0003בפרה ששותה ראשון ראשון\u0004 שלא אדם הוא שהוציא את המיצוי הראשון או השני וכו' מן הכלי, אלא פרה (שאינה גורמת למי גשמים להכשיר אוכלים) היא ששתתה, ומפיה נטף המשקה על אוכלים. ולפיכך, רק אם הוא נחשב ליין — הריהו מכשיר את האוכל לקבל טומאה, ואם לא — מי גשמים הוא ואינו מכשיר.","\u0003אמר רב זוטרא בר טוביה אמר רב: אין אומרים קידוש היום\u0004 (של שבת וחג) \u0003אלא על היין הראוי לינסך על גבי המזבח.\u0004","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא כלל זה? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003יין מגתו,\u0004 מיץ ענבים שבא מיד מן הגת, עוד לפני שתסס — \u0003והא תאני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: יין מגתו לא יביא\u0004 לנסכים למזבח, \u0003ואם הביא\u0004 — \u0003כשר; וכיון\u0004 ש\u0003אם הביא כשר\u0004 למזבח, \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יכולים לעשות עליו קידוש!"],["\u0003אמר רבא: סוחט אדם אשכול של ענבים ואומר עליו\u0004 על המיץ היוצא ממנו \u0003קידוש היום,\u0004 ואינו צריך להמתין עד שייעשה יין!","\u0003ואלא\u0004 תאמר שבא רב \u0003למעוטי\u0004 \u0005[למעט]\u0006 יין הבא \u0003מפיה ומשוליה\u0004 (תחתיתה) של החבית, שיש בפיה תערובת יין וקמחים שונים ובשוליה יש שמרים, \u0003ו\u0004אולם גם כאן \u0003הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003ר' חייא: מפיה ומשוליה\u0004 של חבית \u0003לא יביא\u0004 יין לנסכים, \u0003ואם הביא\u0004 — \u0003כשר,\u0004 ואם כן, הוא כשר אף לכתחילה לקידוש!","\u0003ואלא\u0004 תאמר שבא רב \u0003למעוטי\u0004 \u0005[למעט]\u0006 סוגי יין גרועים, כגון: \u0003יין כושי\u0004 (שחור), \u0003בורק\u0004 (לבן), \u0003היליסטון\u0004 (מתוק), יין \u0003של מרתף,\u0004 כלומר, יין סתם שלא נבדק ויש חשש שכולו או מקצתו החמיץ, וכן יין \u0003של צמוקים?\u0004 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בכולן,\u0004 בכל אלה שנזכרו, \u0003לא יביא\u0004 לנסכים, \u0003ואם הביא\u0004 — \u0003כשר,\u0004 וכל שכן שיהא כשר לקידוש!","\u0003ואלא\u0004 תאמר שבא רב \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003יין קוסס\u0004 (שהחל להחמיץ), או \u0003מזוג\u0004 במים, או \u0003מגולה\u0004 שנתגלה כיסויו ויש חשש ששתה ממנו נחש, \u0003ושל שמרים\u0004 שמיצו מהם יין, \u0003ו\u0004יין \u0003שריחו רע, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בכולן,\u0004 בכל אלה שנזכרו \u0003לא יביא\u0004 לנסכים, \u0003ואם הביא\u0004 — \u0003פסול,\u0004 ועדיין יש לשאול: מבין כל אלה הנזכרים","\u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 לענין קידוש אמר רב? \u0003אי למעוטי\u0004 \u0005[אם למעט]\u0006 יין \u0003קוסס,\u0004 הרי \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יוחנן ור' יהושע בן לוי היא\u0004 (לעיל בבא בתרא צו,א), האם יין כזה בכלל נחשב יין!","\u0003אי למעוטי\u0004 \u0005[אם למעט]\u0006 יין \u0003מזוג,\u0004 הלא \u0003עלויי עלייה\u0004 \u0005[עילה\u0006 השביח \u0005אותו]\u0006 על ידי המזיגה, ש\u0003אמר ר' יוסי בר' חנינא:\u0004 אף שחכמים סבורים שמברכים \"הגפן\" על יין גם כשאינו מזוג, שלא כדעת ר' אליעזר, מכל מקום \u0003מודים חכמים לר' אליעזר בכוס של ברכה, שאין מברכין עליו עד שיתן לתוכו מים,\u0004 משמע שלענין ברכה וקידוש דווקא יין מזוג הוא המובחר!","\u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מגולה,\u0004 אין צריך לומר שאין אומרים עליו קידוש, כי \u0003סכנה היא\u0004 בכלל לשתות ממנו, שמא שתה ממנו נחש והטיל בו ארס!","\u0003אי למעוטי\u0004 \u0005[אם למעט]\u0006 יין \u0003של שמרים, היכי דמי\u0004 \u0005[כיצד היה בדיוק]?\u0006 \u0003אי דרמא תלתא ואתא\u0004 \u0005[אם שהטיל\u0006 \u0005שלוש\u0006 מידות מים לתוך השמרים \u0005ובא,\u0006 יצא\u0005]\u0006 משם משקה שיש בו \u0003ארבעה\u0004 מידות, והלא \u0003חמרא מעליא\u0004 \u0005[יין מעולה]\u0006 \u0003הוא! אי דרמא תלתא ואתא תלתא ופלגא\u0004 \u0005[אם שהטיל שלושה ובא,\u0006 יצא, משקה שיש בו \u0005שלושה ומחצה],\u0006 \u0003פלוגתא דרבנן\u0004 \u0005[מחלוקת של חכמים]\u0006 \u0003ואחרים היא,\u0004 והלכה כחכמים, שאין זה קרוי יין כלל!","\u0003אלא\u0004 יש לומר, שרב בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 יין \u0003שריחו רע\u0004 שאין מקדשים עליו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 יין \u0003מגולה. ואף על גב דעבריה\u0004 \u0005[ואף על פי שהעביר אותו]\u0006 \u0003במסננת, כ\u0004דברי \u0003ר' נחמיה\u0004 שלדעתו על ידי כך מיתקן היין ואין חשש לסכנה, \u0003אפילו הכי\u0004 \u0005[כך]\u0006 אמר רב שפסול הוא לקידוש, משום שנאמר: \u0003\"הקריבהו נא לפחתך הירצך או הישא פניך\"\u0004 (מלאכי א, ח), שמכאן למדים כי דבר שאין נותנים אותו כמתנה לאדם חשוב אף אין משתמשים בו לצורך גבוה.","ועוד בענין זה של יין הכשר לקידוש, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב כהנא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003רב משרשיא מרבא: חמר חווריין\u0004 \u0005[יין לבן],\u0006 \u0003מהו\u0004 דינו, האם מותר להשתמש בו לצורך נסכים או קידוש? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הרי נאמר: \u0003\"אל תרא יין כי יתאדם\"\u0004 (משלי כג, לא), משמע שהצבע האדום הוא שבחו של היין, ואם אינו אדום אינו ראוי.","שנינו במשנה שבמכירת \u0003קנקנים בשרון\u0004 מקבל הקונה על עצמו עשר פיטסות (קנקנים שאינם עשויים כל צורכם) למאה. \u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 שמכל מקום אינו מקבל עליו אלא \u0003פיטסות\u0004 (כדים גדולים) \u0003נאות ומגופרות\u0004 שעשו אותן עם גופרית כדי לחזקן. ואם לא כן — אינו מקבל, לפי שהן לא ראויות מתחילתן כלל לשימוש.","\u0003המוכר יין לחבירו והחמיץ\u0004 היין לאחר מכן — \u0003אינו חייב באחריותו,\u0004 ופטור המוכר מלשלם ללוקח. אבל \u0003אם ידוע שיינו\u0004 של מוכר זה \u0003מחמיץ\u0004 — \u0003הרי זה מקח טעות,\u0004 שהרי התכוון הקונה לקנות יין המשתמר. \u0003ואם אמר לו\u0004 המוכר: \u0003\"יין\u0004"]]};
